export type ViewerFormat =
  | "pdf"
  | "image"
  | "text"
  | "csv"
  | "docx"
  | "xlsx"
  | "pptx"
  | "file";

export type ViewerErrorDomain =
  | "resource"
  | "format"
  | "state"
  | "unsupported"
  | "unknown";

export type ResourceErrorKind =
  | "fetch_failed"
  | "http_error"
  | "aborted"
  | "invalid_range"
  | "partial_content"
  | "too_large"
  | "unsupported_capability"
  | "unknown";

export type ResourceTooLargeReason = "bytes" | "lines";

export class ResourceError extends Error {
  readonly domain = "resource";
  readonly kind: ResourceErrorKind;
  readonly status?: number;
  readonly tooLargeReason?: ResourceTooLargeReason;
  override readonly cause?: unknown;

  constructor({
    kind,
    message,
    status,
    tooLargeReason,
    cause,
  }: {
    kind: ResourceErrorKind;
    message: string;
    status?: number;
    tooLargeReason?: ResourceTooLargeReason;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ResourceError";
    this.kind = kind;
    this.status = status;
    this.tooLargeReason = tooLargeReason;
    this.cause = cause;
  }
}

export type ViewerFormatErrorKind =
  | "bounds"
  | "decode_failed"
  | "disposed"
  | "index_out_of_range"
  | "load_failed"
  | "parse_failed"
  | "render_failed"
  | "worker_failed"
  | "unknown";

export interface ViewerFormatErrorMapperOptions {
  kind: ViewerFormatErrorKind;
  message: string;
}

export class ViewerFormatError extends Error {
  readonly domain = "format";
  readonly format: ViewerFormat;
  readonly kind: ViewerFormatErrorKind;
  override readonly cause?: unknown;

  constructor({
    format,
    kind,
    message,
    cause,
  }: {
    format: ViewerFormat;
    kind: ViewerFormatErrorKind;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerFormatError";
    this.format = format;
    this.kind = kind;
    this.cause = cause;
  }
}

export type ViewerStateErrorKind =
  | "invalid_bounds"
  | "invalid_target"
  | "out_of_range"
  | "stale_resource"
  | "unknown";

export class ViewerStateError extends Error {
  readonly domain = "state";
  readonly format?: ViewerFormat;
  readonly kind: ViewerStateErrorKind;
  override readonly cause?: unknown;

  constructor({
    format,
    kind,
    message,
    cause,
  }: {
    format?: ViewerFormat;
    kind: ViewerStateErrorKind;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerStateError";
    this.format = format;
    this.kind = kind;
    this.cause = cause;
  }
}

export class ViewerUnsupportedError extends Error {
  readonly domain = "unsupported";
  readonly format?: ViewerFormat;
  readonly sourceKind?: string;
  override readonly cause?: unknown;

  constructor({
    format,
    sourceKind,
    message,
    cause,
  }: {
    format?: ViewerFormat;
    sourceKind?: string;
    message: string;
    cause?: unknown;
  }) {
    super(message);
    this.name = "ViewerUnsupportedError";
    this.format = format;
    this.sourceKind = sourceKind;
    this.cause = cause;
  }
}

export interface ViewerErrorInfo {
  domain: ViewerErrorDomain;
  format?: ViewerFormat;
  kind: string;
  message: string;
  status?: number;
  isRetryable: boolean;
  isDownloadUseful: boolean;
  userMessage: string;
  cause?: unknown;
}

export interface ViewerErrorContext {
  format?: ViewerFormat;
  sourceKind?: "url" | "blob" | "text";
  canDownload?: boolean;
  retry?: "auto" | "always" | "never";
}

export function isAbortError(error: unknown): boolean {
  return (
    (error instanceof DOMException && error.name === "AbortError") ||
    (error instanceof Error && error.name === "AbortError")
  );
}

export function isResourceError(error: unknown): error is ResourceError {
  return (
    error instanceof ResourceError ||
    isErrorLike(error, "ResourceError", "resource")
  );
}

export function isViewerFormatError(
  error: unknown,
): error is ViewerFormatError {
  return (
    error instanceof ViewerFormatError ||
    isErrorLike(error, "ViewerFormatError", "format")
  );
}

export function isViewerStateError(error: unknown): error is ViewerStateError {
  return (
    error instanceof ViewerStateError ||
    isErrorLike(error, "ViewerStateError", "state")
  );
}

export function isViewerUnsupportedError(
  error: unknown,
): error is ViewerUnsupportedError {
  return (
    error instanceof ViewerUnsupportedError ||
    isErrorLike(error, "ViewerUnsupportedError", "unsupported")
  );
}

export function toViewerErrorInfo(
  error: unknown,
  context: ViewerErrorContext = {},
): ViewerErrorInfo {
  const canDownload = context.canDownload ?? true;

  if (isResourceError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: error.kind,
      message: error.message,
      status: error.status,
      isRetryable: retryable(
        context,
        resourceErrorDefaultRetry(error, context),
      ),
      isDownloadUseful: canDownload && error.kind !== "aborted",
      userMessage: resourceErrorUserMessage(error),
      cause: error.cause,
    };
  }

  if (isViewerFormatError(error)) {
    const format = error.format ?? context.format;
    return {
      domain: "format",
      format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(
        context,
        formatErrorDefaultRetry(error, context, format),
      ),
      isDownloadUseful: canDownload,
      userMessage: formatErrorUserMessage(format, error.kind, error),
      cause: error.cause,
    };
  }

  if (isViewerStateError(error)) {
    return {
      domain: "state",
      format: error.format ?? context.format,
      kind: error.kind,
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: stateErrorUserMessage(error.kind),
      cause: error.cause,
    };
  }

  if (isViewerUnsupportedError(error)) {
    return {
      domain: "unsupported",
      format: error.format ?? context.format,
      kind: "unsupported",
      message: error.message,
      isRetryable: retryable(context, false),
      isDownloadUseful: canDownload,
      userMessage: "This file cannot be previewed here.",
      cause: error.cause,
    };
  }

  if (isAbortError(error)) {
    return {
      domain: "resource",
      format: context.format,
      kind: "aborted",
      message: "Loading was cancelled.",
      isRetryable: retryable(context, false),
      isDownloadUseful: false,
      userMessage: "Loading was cancelled.",
      cause: error,
    };
  }

  const message = error instanceof Error ? error.message : String(error);
  return {
    domain: "unknown",
    format: context.format,
    kind: "unknown",
    message,
    isRetryable: retryable(context, unknownErrorDefaultRetry(context)),
    isDownloadUseful: canDownload,
    userMessage: fallbackUserMessage(context.format),
    cause: error,
  };
}

function isErrorLike(error: unknown, name: string, domain: ViewerErrorDomain) {
  if (!error || typeof error !== "object") return false;
  const candidate = error as {
    name?: unknown;
    domain?: unknown;
    kind?: unknown;
  };
  return (
    (candidate.name === name || candidate.domain === domain) &&
    typeof candidate.kind === "string"
  );
}

function retryable(context: ViewerErrorContext, fallback: boolean) {
  if (context.retry === "always") return true;
  if (context.retry === "never") return false;
  return fallback;
}

function resourceErrorDefaultRetry(
  error: ResourceError,
  context: ViewerErrorContext,
) {
  if (error.kind === "aborted") return false;
  if (error.kind === "invalid_range") return false;
  if (error.kind === "too_large") return false;
  if (error.kind === "unsupported_capability") return false;
  return context.sourceKind === "url";
}

function formatErrorDefaultRetry(
  error: ViewerFormatError,
  context: ViewerErrorContext,
  format: ViewerFormat | undefined,
) {
  if (format === "text" && error.kind === "bounds") return false;
  if (error.kind === "disposed") return false;
  if (error.kind === "index_out_of_range") return false;
  if (format === "docx") return true;
  return context.sourceKind === "url";
}

function unknownErrorDefaultRetry(context: ViewerErrorContext) {
  if (context.format === "docx") return true;
  return context.sourceKind === "url";
}

function resourceErrorUserMessage(error: ResourceError) {
  if (error.kind === "http_error") {
    return error.status
      ? `Failed to load file: ${error.status}.`
      : "Couldn't load this file.";
  }
  if (error.kind === "fetch_failed") return "Couldn't load this file.";
  if (error.kind === "aborted") return "Loading was cancelled.";
  if (error.kind === "invalid_range") return "This source range is invalid.";
  if (error.kind === "too_large") {
    return error.tooLargeReason === "lines"
      ? "This file has too many lines to preview."
      : "This file is too large to preview.";
  }
  if (error.kind === "partial_content") {
    return "This source returned partial content and cannot be previewed here.";
  }
  if (error.kind === "unsupported_capability") {
    return "This source cannot be previewed here.";
  }
  return "Couldn't load this file.";
}

function formatErrorUserMessage(
  format: ViewerFormat | undefined,
  kind: string,
  error?: unknown,
) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") {
    if (kind === "index_out_of_range")
      return "This image page is out of range.";
    if (kind === "decode_failed") return "Couldn't decode this image.";
    return "Couldn't load this image.";
  }
  if (format === "text") {
    if (kind === "render_failed") return "Couldn't render this text file.";
    if (kind === "bounds") {
      const boundsError = error as {
        reason?: unknown;
        boundName?: unknown;
      };
      if (boundsError.reason === "lines") {
        return "This text file has too many lines to preview.";
      }
      if (boundsError.reason === "bytes") {
        return "This text file is too large to preview.";
      }
      if (typeof boundsError.boundName === "string") {
        return "Text viewer bounds are invalid.";
      }
    }
    return "Couldn't load this text file.";
  }
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't render this document.";
  if (format === "xlsx") return "Couldn't parse this spreadsheet.";
  if (format === "pptx") {
    if (kind === "render_failed") return "Couldn't render this slide.";
    return "Couldn't load this presentation.";
  }
  return "Couldn't load this file.";
}

function stateErrorUserMessage(kind: ViewerStateErrorKind) {
  if (kind === "invalid_bounds") return "Viewer bounds are invalid.";
  if (kind === "invalid_target") return "The requested target is invalid.";
  if (kind === "out_of_range") return "The requested item is out of range.";
  if (kind === "stale_resource") return "This viewer state is no longer valid.";
  return "Couldn't load this file.";
}

function fallbackUserMessage(format: ViewerFormat | undefined) {
  if (format === "pdf") return "Couldn't load this PDF.";
  if (format === "image") return "Couldn't load this image.";
  if (format === "text") return "Couldn't load this text file.";
  if (format === "csv") return "Couldn't parse this table.";
  if (format === "docx") return "Couldn't load this document.";
  if (format === "xlsx") return "Couldn't load this spreadsheet.";
  if (format === "pptx") return "Couldn't load this presentation.";
  return "Couldn't load this file.";
}

import type * as React from "react";

import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source";

export interface ImageFrameOverlayProps {
  /** 1-based frame index (a TIFF page; always 1 for single images). */
  frameNumber: number;
  /** Rendered frame size in CSS pixels (post-scale, post-rotation). */
  width: number;
  height: number;
  scale: number;
  rotation: number;
}

export interface ImageFrameRenderTiming {
  cached: boolean;
  durationMs: number;
  frameNumber: number;
  pixelRatio: number;
  renderScale: number;
  status: "rendered" | "cancelled" | "failed";
}

/**
 * Imperative handle for driving the viewer from outside (e.g. scroll to the
 * source of a hovered field). Obtain it with a `ref` on `<ImageViewer>`.
 */
export interface ImageViewerHandle {
  /**
   * Scroll a frame's normalized area into view. `area` fields are percentages
   * [0, 100] of the rendered frame; only `top` is required. Pass
   * `behavior: "auto"` for an instant jump (e.g. on hover).
   */
  scrollToFrameArea: (
    frameNumber: number,
    area: { top: number; left?: number; width?: number; height?: number },
    options?: ScrollToOptions,
  ) => void;
  /** The scrolling viewport element, or null before the image loads. */
  getViewportElement: () => HTMLDivElement | null;
}

export type ImageDocumentSource = UrlViewerSource | BlobViewerSource;

export interface ImageViewerProps {
  /** Canonical image source. PNG/JPEG/WebP/GIF/AVIF/BMP/ICO or TIFF. */
  source: ImageDocumentSource;
  className?: string;
  /** Fixed scale; when omitted the viewer fits frame width to the container. */
  scale?: number;
  /** Initial uncontrolled scale. When omitted, uncontrolled mode starts fit-width. */
  defaultScale?: number;
  /** Intrinsic size used to reserve the first frame while image metadata loads. */
  fallbackFrameSize?: { width: number; height: number };
  /** Called by zoom controls. `null` means return to fit-width mode. */
  onScaleChange?: (scale: number | null) => void;
  controls?: boolean;
  /** Show download actions in this viewer's controls/error state. */
  download?: boolean;
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each frame. */
  renderFrameOverlay?: (props: ImageFrameOverlayProps) => React.ReactNode;
  /** Reports measured canvas render work for benchmark and profiling surfaces. */
  onFrameRenderTiming?: (timing: ImageFrameRenderTiming) => void;
  /** Fired with the 1-based frame nearest the top of the viewport as you scroll. */
  onVisibleFrameChange?: (frameNumber: number) => void;
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void;
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean;
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { type FrameSource } from "@/lib/image-frame-source";
import {
  imageFrameSourceManager,
  type FrameSourceLease,
  type ImageSourceContent,
} from "@/lib/image-source-cache";
import { cn } from "@/lib/utils";
import {
  type ViewerContentIdentity,
  type ViewerResource,
} from "@/lib/viewer-resource";
import { ImageFrameScroller } from "@/components/ui/image-viewer-frame";
import {
  IMAGE_READING_MARKER_RATIO,
  MAX_VIEWER_SCALE,
  MIN_VIEWER_SCALE,
  useFrameListWidth,
  useImageViewerHandle,
  useImageViewerScale,
  useVisibleFrame,
} from "@/components/ui/image-viewer-hooks";
import {
  type ImageViewerHandle,
  type ImageViewerProps,
} from "@/components/ui/image-viewer-types";
import {
  useViewerControlsRegistration,
  ViewerControls,
  type ViewerControlsState,
} from "@/components/ui/viewer-controls";

import {
  FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
  readFileViewerBeforeLayoutMotionFrame,
} from "./file-viewer-elements";
import type { FileViewerMotionFrame } from "./file-viewer-motion-plan";
import {
  captureFileViewerFitWidthAnchorScreenOffset,
  createFileViewerFitWidthSurfaceMotionResolver,
  FILE_VIEWER_FIT_WIDTH_ANCHOR_BLOCK_PROPERTY,
  resolveFileViewerFitWidthMotionAnchorBlock,
} from "./file-viewer-fit-width-motion";
import type { FileViewerDocumentSurfaceMotionResolver } from "./file-viewer-motion-kernel";
import { resolveFileViewerRendererLayoutInlineSize } from "./file-viewer-renderer-contract";
import {
  useOptionalFileViewerRendererEnvironment,
  useOptionalFileViewerRendererFrame,
} from "./file-viewer-renderer-frame";
import { useReadingFractionRebase } from "./use-reading-fraction-rebase";
import {
  createImageFrameLayout,
  getCurrentImageFrameNumber,
  getImageFrameLayout,
} from "./image-viewer-virtualization";
import { joinEffectKey } from "@/lib/effect-key";

export function ImageViewerContent({
  resource,
  className,
  scale: controlledScale,
  defaultScale,
  download = true,
  onScaleChange,
  controls = true,
  renderFrameOverlay,
  onFrameRenderTiming,
  onVisibleFrameChange,
  onScrollProgressChange,
  bare = false,
  forwardedRef,
}: Omit<ImageViewerProps, "source"> & {
  forwardedRef?: React.ForwardedRef<ImageViewerHandle>;
  resource: ViewerResource;
}) {
  const frameSource = React.use(getImageSource(resource.content));
  const sourceLeaseRef = useFrameSourceLease(resource.content, frameSource);
  const rendererEnvironment = useOptionalFileViewerRendererEnvironment();
  const { frameListRef, frameListWidth } = useFrameListWidth({
    enabled: !rendererEnvironment.usesShellGeometry,
  });
  const rendererFrame = useOptionalFileViewerRendererFrame({
    fallbackInlineSize: frameListWidth,
  });
  const frameListLayoutWidth = resolveFileViewerRendererLayoutInlineSize({
    fallbackInlineSize: frameListWidth,
    rendererFrame,
  });
  // While the sidebar transition is running, hold the virtualization's
  // mounted-frame window so the reading frames stay mounted through the
  // slide-start commit and the brief settle hold; re-derive the window
  // normally once the transition is idle again.
  const freezeVisibleFrameWindow = rendererFrame.phase !== "idle";
  const {
    isFitWidth,
    rotateClockwise,
    rotation,
    scale,
    scaleControlsDisabled,
    setViewerScale,
    widestFrameWidth,
  } = useImageViewerScale(
    frameSource,
    controlledScale,
    defaultScale,
    onScaleChange,
    frameListLayoutWidth,
  );
  const frameLayout = React.useMemo(
    () =>
      createImageFrameLayout({
        frames: frameSource.frames,
        scale,
        rotation,
      }),
    [frameSource.frames, rotation, scale],
  );
  const {
    currentFrameNumber,
    getScrollMetrics,
    getViewportElement,
    handleScroll,
    scrollToFrameArea,
    setScrollViewportRef,
  } = useVisibleFrame(
    frameLayout,
    frameSource,
    onScrollProgressChange,
    onVisibleFrameChange,
  );
  useImageViewerHandle(forwardedRef, getViewportElement, scrollToFrameArea);

  // Preserve the reading position when the image re-fits to a new width (the
  // sidebar toggle). The fit scale is the layout key; capture the fraction on
  // scroll and restore it the instant the scale changes.
  const scrollerRef = React.useRef<HTMLElement | null>(null);
  const { captureReadingFraction } = useReadingFractionRebase({
    scrollerRef,
    layoutKey: scale,
    enabled: rendererEnvironment.usesShellGeometry,
  });
  const imageDocumentSurfaceRef = React.useRef<HTMLDivElement | null>(null);
  const [imageDocumentSurfaceElement, setImageDocumentSurfaceElement] =
    React.useState<HTMLDivElement | null>(null);
  const resolveSurfaceMotionStyle =
    React.useMemo<FileViewerDocumentSurfaceMotionResolver>(
      () =>
        createFileViewerFitWidthSurfaceMotionResolver({
          align: rendererFrame.align,
          isFitWidth,
          stageInlineSize: frameLayout.maxFrameWidth + frameLayout.padding * 2,
        }),
      [
        frameLayout.maxFrameWidth,
        frameLayout.padding,
        isFitWidth,
        rendererFrame.align,
      ],
    );
  const imageStageInlineSize =
    frameLayout.maxFrameWidth + frameLayout.padding * 2;
  const preMotionAnchorRef = React.useRef<{
    frameNumber: number;
    screenRelTop: number;
  } | null>(null);
  const lastAnchorBlockRef = React.useRef<number | null>(null);
  const writeImageAnchorBlockOffsetPx = React.useCallback(
    (anchorBlock: number) => {
      const element = imageDocumentSurfaceRef.current;
      if (!element) return;
      const safeAnchorBlock = Number.isFinite(anchorBlock) ? anchorBlock : 0;
      lastAnchorBlockRef.current = safeAnchorBlock;
      element.style.setProperty(
        FILE_VIEWER_FIT_WIDTH_ANCHOR_BLOCK_PROPERTY,
        `${safeAnchorBlock}px`,
      );
    },
    [],
  );
  const writeImageDocumentAnchorBlockOffset = React.useCallback(() => {
    const metrics = getScrollMetrics();
    // Stage (physical) coordinates: the transform scales the stage, so the
    // marker offset is anchored to the live DOM scroll position.
    const physicalScrollTop = scrollerRef.current?.scrollTop ?? 0;
    writeImageAnchorBlockOffsetPx(
      Math.max(0, physicalScrollTop) +
        Math.max(0, metrics.viewportHeight) * IMAGE_READING_MARKER_RATIO,
    );
  }, [getScrollMetrics, writeImageAnchorBlockOffsetPx]);
  // The transform must pin the exact screen line the slide-start commit
  // preserved. Measured against the frame layout models (old model at
  // capture, new model at solve) in the stage's PHYSICAL coordinates — the
  // frame offsets are logical, so they are mapped through the paged-scroll
  // delta (logical − physical) like the PDF runtime does. Exact across
  // constant gaps and padding, rebase clamps, paged scroll spaces, and
  // mid-flight retargets (the capture applies the in-flight transform it was
  // seen under).
  const writeImageMotionAnchorBlockOffset = React.useCallback(() => {
    const metrics = getScrollMetrics();
    const physicalScrollTop = scrollerRef.current?.scrollTop ?? 0;
    const logicalDelta = metrics.scrollTop - physicalScrollTop;
    const preMotionAnchor = preMotionAnchorRef.current;
    const newFrameLayout = preMotionAnchor
      ? getImageFrameLayout(frameLayout, preMotionAnchor.frameNumber)
      : null;
    const anchorBlock =
      preMotionAnchor && newFrameLayout
        ? resolveFileViewerFitWidthMotionAnchorBlock({
            fromInlineSize: rendererFrame.fromInlineSize,
            probeScreenOffset: preMotionAnchor.screenRelTop,
            probeStageOffset: newFrameLayout.offsetTop - logicalDelta,
            scrollTop: physicalScrollTop,
            stageInlineSize: imageStageInlineSize,
            toInlineSize: rendererFrame.toInlineSize,
          })
        : null;

    if (anchorBlock == null) {
      writeImageDocumentAnchorBlockOffset();
      return;
    }
    writeImageAnchorBlockOffsetPx(anchorBlock);
  }, [
    frameLayout,
    getScrollMetrics,
    imageStageInlineSize,
    rendererFrame.fromInlineSize,
    rendererFrame.toInlineSize,
    writeImageAnchorBlockOffsetPx,
    writeImageDocumentAnchorBlockOffset,
  ]);
  const measureBeforeLayoutMotionRef = React.useRef(
    (_liveFrame: FileViewerMotionFrame | null) => {},
  );
  measureBeforeLayoutMotionRef.current = (liveFrame) => {
    const metrics = getScrollMetrics();
    const physicalScrollTop = scrollerRef.current?.scrollTop ?? 0;
    const logicalDelta = metrics.scrollTop - physicalScrollTop;
    const frameNumber = getCurrentImageFrameNumber({
      layout: frameLayout,
      scrollTop: metrics.scrollTop,
      viewportHeight: metrics.viewportHeight,
    });
    const frame = getImageFrameLayout(frameLayout, frameNumber);
    preMotionAnchorRef.current = frame
      ? {
          frameNumber,
          screenRelTop: captureFileViewerFitWidthAnchorScreenOffset({
            lastAnchorBlock: lastAnchorBlockRef.current,
            liveFrame,
            probeStageOffset: frame.offsetTop - logicalDelta,
            scrollTop: physicalScrollTop,
            stageInlineSize: imageStageInlineSize,
          }),
        }
      : null;
  };
  const handleBeforeLayoutMotion = React.useCallback(
    (event: Event) => {
      captureReadingFraction();
      measureBeforeLayoutMotionRef.current(
        readFileViewerBeforeLayoutMotionFrame(event),
      );
    },
    [captureReadingFraction],
  );
  // Runs inside the slide-start commit after the fraction rebase (hook order
  // puts the rebase's layout effect first), pinning the transform before the
  // first frame paints. Keyed on the transition id so a mid-flight retarget
  // (same isTransitioning) re-solves against the new motion.
  const isImageShellTransitioning = rendererFrame.isTransitioning;
  const writeImageMotionAnchorBlockOffsetRef = React.useRef(
    writeImageMotionAnchorBlockOffset,
  );
  writeImageMotionAnchorBlockOffsetRef.current =
    writeImageMotionAnchorBlockOffset;
  useKeyedLayoutEffect(
    joinEffectKey([
      "image-motion-anchor",
      isImageShellTransitioning,
      rendererFrame.documentTransition.transitionId,
      writeImageMotionAnchorBlockOffset,
    ]),
    () => {
      if (!isImageShellTransitioning) return;
      writeImageMotionAnchorBlockOffsetRef.current();
    },
  );
  const setImageDocumentSurfaceRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      const previousElement = imageDocumentSurfaceRef.current;
      if (previousElement === element) return;
      previousElement?.removeEventListener(
        FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
        handleBeforeLayoutMotion,
      );
      imageDocumentSurfaceRef.current = element;
      setImageDocumentSurfaceElement((previous) =>
        previous === element ? previous : element,
      );
      if (!element) return;
      element.addEventListener(
        FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
        handleBeforeLayoutMotion,
      );
      writeImageDocumentAnchorBlockOffset();
    },
    [handleBeforeLayoutMotion, writeImageDocumentAnchorBlockOffset],
  );
  const documentSurfaceKey = imageDocumentSurfaceElement
    ? joinEffectKey([
        "image-document-surface",
        imageDocumentSurfaceElement,
        rendererEnvironment.registerDocumentSurface,
        resolveSurfaceMotionStyle,
      ])
    : null;
  useKeyedLayoutEffect(documentSurfaceKey, () => {
    if (!imageDocumentSurfaceElement) return;
    return rendererEnvironment.registerDocumentSurface({
      element: imageDocumentSurfaceElement,
      resolveMotionStyle: resolveSurfaceMotionStyle,
    });
  });
  const setScrollViewportRefWithRebase = React.useCallback(
    (element: HTMLDivElement | null) => {
      scrollerRef.current = element;
      setScrollViewportRef(element);
    },
    [setScrollViewportRef],
  );
  const handleScrollWithRebase = React.useCallback(() => {
    captureReadingFraction();
    handleScroll();
  }, [captureReadingFraction, handleScroll]);

  const frameCount = frameSource.frames.length;
  const countLabel =
    frameSource.kind === "tiff"
      ? `Page ${Math.min(currentFrameNumber, frameCount)} of ${frameCount}`
      : `${frameCount} image${frameCount === 1 ? "" : "s"}`;
  const zoomOut = React.useCallback(
    () =>
      setViewerScale(clamp(scale / 1.2, MIN_VIEWER_SCALE, MAX_VIEWER_SCALE)),
    [scale, setViewerScale],
  );
  const zoomIn = React.useCallback(
    () =>
      setViewerScale(clamp(scale * 1.2, MIN_VIEWER_SCALE, MAX_VIEWER_SCALE)),
    [scale, setViewerScale],
  );
  const fitWidth = React.useCallback(
    () => setViewerScale(null),
    [setViewerScale],
  );
  useImageControlsRegistration({
    countLabel,
    download,
    downloadAction: resource.originalDownload,
    fitWidth,
    rotateClockwise,
    scale,
    scaleControlsDisabled,
    zoomIn,
    zoomOut,
  });

  return (
    <div
      ref={sourceLeaseRef}
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "bg-muted/20 h-full" : "bg-muted/30 rounded-xl border",
        className,
      )}
      data-slot="image-viewer"
    >
      {controls ? (
        <ViewerControls
          position={{ label: countLabel }}
          zoom={{
            scale,
            onZoomOut: zoomOut,
            onZoomIn: zoomIn,
            onFit: fitWidth,
            isDisabled: scaleControlsDisabled,
          }}
          rotate={{ onRotate: rotateClockwise }}
          downloads={download ? [resource.originalDownload] : []}
        />
      ) : null}

      <div className="flex min-h-0 flex-1">
        <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
          <div className="relative flex min-h-0 flex-1 flex-col">
            <ImageFrameScroller
              source={frameSource}
              layout={frameLayout}
              scale={scale}
              rotation={rotation}
              documentSurfaceRef={setImageDocumentSurfaceRef}
              frameListRef={frameListRef}
              getScrollMetrics={getScrollMetrics}
              freezeVisibleFrameWindow={freezeVisibleFrameWindow}
              viewportRef={setScrollViewportRefWithRebase}
              onScroll={handleScrollWithRebase}
              renderFrameOverlay={renderFrameOverlay}
              onFrameRenderTiming={onFrameRenderTiming}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

function useImageControlsRegistration({
  countLabel,
  download,
  downloadAction,
  fitWidth,
  rotateClockwise,
  scale,
  scaleControlsDisabled,
  zoomIn,
  zoomOut,
}: {
  countLabel: string;
  download: boolean;
  downloadAction: ViewerResource["originalDownload"];
  fitWidth: () => void;
  rotateClockwise: () => void;
  scale: number;
  scaleControlsDisabled: boolean;
  zoomIn: () => void;
  zoomOut: () => void;
}) {
  const onControlsChange = useViewerControlsRegistration();
  const controlsState = React.useMemo<ViewerControlsState>(
    () => ({
      position: { label: countLabel },
      zoom: {
        scale,
        onZoomOut: zoomOut,
        onZoomIn: zoomIn,
        onFit: fitWidth,
        isDisabled: scaleControlsDisabled,
      },
      rotate: { onRotate: rotateClockwise },
      downloads: download ? [downloadAction] : [],
    }),
    [
      countLabel,
      download,
      downloadAction,
      fitWidth,
      rotateClockwise,
      scale,
      scaleControlsDisabled,
      zoomIn,
      zoomOut,
    ],
  );

  useKeyedMountEffect(
    joinEffectKey(["image-controls", onControlsChange, controlsState]),
    () => {
      if (!onControlsChange) return;
      onControlsChange(controlsState);
      return () => onControlsChange(null);
    },
  );
}

export function getImageSource(
  content: ImageSourceContent,
): Promise<FrameSource> {
  return imageFrameSourceManager.load(content, createTiffWorker);
}

export function resetImageSourceCacheForTests() {
  imageFrameSourceManager.clear();
}

function useFrameSourceLease(
  content: ViewerContentIdentity,
  source: FrameSource,
): React.RefCallback<HTMLDivElement> {
  return React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      const lease = retainImageSource(content, source);
      return () => lease?.release();
    },
    [content, source],
  );
}

function retainImageSource(
  content: ViewerContentIdentity,
  source: FrameSource,
): FrameSourceLease | null {
  return imageFrameSourceManager.retain(content, source);
}

function createTiffWorker() {
  return new Worker(new URL("./image-viewer.worker", import.meta.url), {
    type: "module",
  });
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { type FrameSource } from "@/lib/image-frame-source";
import { normalizeRotation, rotatedSize } from "@/lib/image-geometry";
import {
  type ImageViewerHandle,
  type ImageViewerProps,
} from "@/components/ui/image-viewer-types";

import {
  getCurrentImageFrameNumber,
  getImageFrameLayout,
  getImageLogicalScrollTop,
  getImagePhysicalScrollHeight,
  resolveImagePhysicalScrollPosition,
  type ImageFrameVirtualizationScrollMetrics,
  type ImageFrameLayoutModel,
} from "./image-viewer-virtualization";
import type {
  ViewerDocumentLayoutModel,
  ViewerDocumentScrollMapper,
  ViewerDocumentScrollMetrics,
  ViewerDocumentScrollTargetResolver,
} from "./viewer-types";
import { useViewerDocumentScroll } from "./viewer-document-scroll";
import { getFileViewerFitWidthScale } from "./file-viewer-fit-width-motion";
import { joinEffectKey } from "@/lib/effect-key";

const IMAGE_SCROLL_HEADROOM = 48;
export const IMAGE_READING_MARKER_RATIO = 0.2;
export const IMAGE_VIEWER_HORIZONTAL_PADDING = 32;

/** Bounds for the viewer's zoom range, shared by fit-width and the controls. */
export const MIN_VIEWER_SCALE = 0.25;
export const MAX_VIEWER_SCALE = 5;

export function useFrameListWidth({
  enabled = true,
}: {
  enabled?: boolean;
} = {}) {
  const [frameListWidth, setFrameListWidth] = React.useState<number | null>(
    null,
  );
  const frameListRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      if (!enabled) {
        setFrameListWidth(null);
        return;
      }

      setFrameListWidth(element.clientWidth);
      const observer = new ResizeObserver((entries) => {
        for (const entry of entries) {
          setFrameListWidth((entry.target as HTMLElement).clientWidth);
        }
      });
      observer.observe(element);
      return () => observer.disconnect();
    },
    [enabled],
  );

  return { frameListRef, frameListWidth };
}

export function useImageViewerScale(
  source: FrameSource,
  controlledScale: number | undefined,
  defaultScale: number | undefined,
  onScaleChange: ImageViewerProps["onScaleChange"],
  frameListWidth: number | null,
) {
  const isScaleControlled = controlledScale !== undefined;
  const [uncontrolledScale, setUncontrolledScale] = React.useState<
    number | null
  >(() =>
    defaultScale === undefined ? null : normalizeViewerScale(defaultScale),
  );
  const [rawRotation, setRawRotation] = React.useState(0);

  useKeyedMountEffect(
    joinEffectKey(["image-scale-reset", defaultScale, source]),
    () => {
      setRawRotation(0);
      setUncontrolledScale(
        defaultScale === undefined ? null : normalizeViewerScale(defaultScale),
      );
    },
  );

  const rotation = normalizeRotation(rawRotation);
  const widestFrameWidth = Math.max(
    1,
    ...source.frames.map(
      (frame) => rotatedSize(frame.intrinsicSize, rotation).width,
    ),
  );
  const fitWidthScale = frameListWidth
    ? getFileViewerFitWidthScale({
        availableInlineSize: frameListWidth,
        contentInlineSize: widestFrameWidth,
        stageInlinePadding: IMAGE_VIEWER_HORIZONTAL_PADDING,
      })
    : 1;
  const scale =
    controlledScale !== undefined
      ? normalizeViewerScale(controlledScale)
      : uncontrolledScale !== null
        ? normalizeViewerScale(uncontrolledScale)
        : Math.min(MAX_VIEWER_SCALE, Math.max(MIN_VIEWER_SCALE, fitWidthScale));
  const isFitWidth =
    controlledScale === undefined && uncontrolledScale === null;

  const scaleControlsDisabled = isScaleControlled && !onScaleChange;
  const setViewerScale = React.useCallback(
    (nextScale: number | null) => {
      const normalized =
        nextScale == null ? null : normalizeViewerScale(nextScale);
      if (isScaleControlled) {
        onScaleChange?.(normalized);
        return;
      }
      setUncontrolledScale(normalized);
    },
    [isScaleControlled, onScaleChange],
  );
  const rotateClockwise = React.useCallback(() => {
    setRawRotation((value) => (value + 90) % 360);
  }, []);

  return {
    isFitWidth,
    rotateClockwise,
    rotation,
    scale,
    scaleControlsDisabled,
    setViewerScale,
    widestFrameWidth,
  };
}

function normalizeViewerScale(scale: number): number {
  return Number.isFinite(scale) && scale > 0
    ? Math.min(MAX_VIEWER_SCALE, Math.max(MIN_VIEWER_SCALE, scale))
    : MIN_VIEWER_SCALE;
}

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

function normalizeFrameAreaPercent(value: number): number | null {
  if (!Number.isFinite(value)) return null;
  return Math.min(100, Math.max(0, value));
}

type ImageReadingAnchor =
  | {
      kind: "top";
    }
  | {
      frameNumber: number;
      kind: "frame";
      yPercent: number;
    };

type ImageFrameArea = Parameters<ImageViewerHandle["scrollToFrameArea"]>[1];

type ImageFrameAreaTarget = {
  area: ImageFrameArea;
  frameNumber: number;
};

type ImageDocumentLayoutModel = ViewerDocumentLayoutModel<ImageReadingAnchor>;

const IMAGE_DOCUMENT_SCROLL_MAPPER: ViewerDocumentScrollMapper = {
  getLogicalScrollTop: ({
    blockSize,
    physicalScrollTop,
    scrollPageOffset,
    viewportBlockSize,
  }) =>
    getImageLogicalScrollTop({
      physicalScrollTop,
      scrollPageOffset,
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
  getPhysicalScrollSize: ({ blockSize, viewportBlockSize }) =>
    getImagePhysicalScrollHeight({
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
  resolvePhysicalScrollPosition: ({
    blockSize,
    logicalScrollTop,
    scrollPageOffset,
    viewportBlockSize,
  }) =>
    resolveImagePhysicalScrollPosition({
      logicalScrollTop,
      scrollPageOffset,
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
};

export function useVisibleFrame(
  layout: ImageFrameLayoutModel,
  resetKey: unknown,
  onScrollProgressChange: ImageViewerProps["onScrollProgressChange"],
  onVisibleFrameChange: ImageViewerProps["onVisibleFrameChange"],
) {
  const [currentFrameNumber, setCurrentFrameNumber] = React.useState(1);
  const lastReportedFrameNumber = React.useRef(0);
  const documentLayout = React.useMemo(
    () => createImageDocumentLayoutModel(layout),
    [layout],
  );
  const resolveScrollTarget = React.useCallback<
    ViewerDocumentScrollTargetResolver<ImageReadingAnchor, ImageFrameAreaTarget>
  >(({ target }) => getImageFrameAreaScrollTarget(layout, target), [layout]);
  const documentScroll = useViewerDocumentScroll({
    copyScrollTarget: copyImageFrameAreaTarget,
    layout: documentLayout,
    resetKey,
    resolveScrollTarget,
    scrollMapper: IMAGE_DOCUMENT_SCROLL_MAPPER,
  });
  const getScrollMetrics = React.useCallback(
    () =>
      toImageFrameVirtualizationScrollMetrics(
        documentScroll.getScrollMetrics(),
      ),
    [documentScroll],
  );

  const handleScroll = React.useCallback(() => {
    const viewport = documentScroll.getViewportElement();
    if (!viewport) return;
    documentScroll.handleScroll();

    const metrics = documentScroll.getScrollMetrics();
    const isRebased = metrics.physicalScrollSize < documentLayout.blockSize;
    const scrollable = isRebased
      ? documentLayout.blockSize - metrics.viewportBlockSize
      : viewport.scrollHeight - metrics.viewportBlockSize;
    const progress =
      scrollable > 0
        ? clamp01(
            (isRebased ? metrics.scrollTop : viewport.scrollTop) / scrollable,
          )
        : 0;
    onScrollProgressChange?.(progress);

    const frameNumber = getCurrentImageFrameNumber({
      layout,
      scrollTop: metrics.scrollTop,
      viewportHeight: metrics.viewportBlockSize,
    });
    if (frameNumber && frameNumber !== lastReportedFrameNumber.current) {
      lastReportedFrameNumber.current = frameNumber;
      setCurrentFrameNumber(frameNumber);
      onVisibleFrameChange?.(frameNumber);
    }
  }, [
    documentLayout,
    documentScroll,
    layout,
    onScrollProgressChange,
    onVisibleFrameChange,
  ]);

  const scrollToFrameArea = React.useCallback(
    (frameNumber: number, area: ImageFrameArea, options?: ScrollToOptions) => {
      documentScroll.scrollToTarget({ area, frameNumber }, options);
    },
    [documentScroll],
  );

  useKeyedMountEffect(joinEffectKey(["image-visible-reset", resetKey]), () => {
    lastReportedFrameNumber.current = 0;
    setCurrentFrameNumber(1);
  });

  return {
    currentFrameNumber,
    getScrollMetrics,
    getViewportElement: documentScroll.getViewportElement,
    handleScroll,
    scrollToFrameArea,
    scrollViewportElement: documentScroll.viewportElement,
    setScrollViewportRef: documentScroll.setViewportElement,
  };
}

function captureImageReadingAnchor(
  layout: ImageFrameLayoutModel,
  {
    scrollTop,
    viewportBlockSize,
  }: {
    scrollTop: number;
    viewportBlockSize: number;
  },
): ImageReadingAnchor | null {
  if (layout.frameCount === 0) return null;
  if (scrollTop <= 0) return { kind: "top" };

  const markerOffset =
    scrollTop + viewportBlockSize * IMAGE_READING_MARKER_RATIO;
  const frameNumber = getCurrentImageFrameNumber({
    layout,
    scrollTop,
    viewportHeight: viewportBlockSize,
  });
  const frame = getImageFrameLayout(layout, frameNumber);
  if (!frame || frame.height <= 0) return null;

  return {
    frameNumber,
    kind: "frame",
    yPercent: clamp01((markerOffset - frame.offsetTop) / frame.height),
  };
}

function getImageReadingAnchorScrollTop(
  layout: ImageFrameLayoutModel,
  {
    anchor,
    viewportBlockSize,
  }: {
    anchor: ImageReadingAnchor;
    viewportBlockSize: number;
  },
): number | null {
  if (anchor.kind === "top") {
    return 0;
  }

  const frame = getImageFrameLayout(layout, anchor.frameNumber);
  if (!frame) return null;

  const targetTop =
    frame.offsetTop +
    frame.height * anchor.yPercent -
    viewportBlockSize * IMAGE_READING_MARKER_RATIO;
  const maxScrollTop = Math.max(0, layout.totalHeight - viewportBlockSize);
  return Math.min(maxScrollTop, Math.max(0, targetTop));
}

export function useImageViewerHandle(
  forwardedRef: React.ForwardedRef<ImageViewerHandle> | undefined,
  getViewportElement: () => HTMLDivElement | null,
  scrollToFrameArea: (
    frameNumber: number,
    area: ImageFrameArea,
    options?: ScrollToOptions,
  ) => void,
) {
  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      scrollToFrameArea,
      getViewportElement,
    }),
    [getViewportElement, scrollToFrameArea],
  );
}

function createImageDocumentLayoutModel(
  layout: ImageFrameLayoutModel,
): ImageDocumentLayoutModel {
  return {
    blockSize: layout.totalHeight,
    captureReadingAnchor: (input) => captureImageReadingAnchor(layout, input),
    getReadingAnchorScrollTop: (target) =>
      getImageReadingAnchorScrollTop(layout, target),
    inlineSize: layout.maxFrameWidth,
  };
}

function getImageFrameAreaScrollTarget(
  layout: ImageFrameLayoutModel,
  target: ImageFrameAreaTarget,
) {
  const areaTop = normalizeFrameAreaPercent(target.area.top);
  if (areaTop == null) return null;

  const frame = getImageFrameLayout(layout, target.frameNumber);
  if (!frame) return null;

  return {
    top: Math.max(
      0,
      frame.offsetTop + (areaTop / 100) * frame.height - IMAGE_SCROLL_HEADROOM,
    ),
  };
}

function copyImageFrameAreaTarget(
  target: ImageFrameAreaTarget,
): ImageFrameAreaTarget {
  return {
    frameNumber: target.frameNumber,
    area: {
      top: target.area.top,
      left: target.area.left,
      width: target.area.width,
      height: target.area.height,
    },
  };
}

function toImageFrameVirtualizationScrollMetrics(
  metrics: ViewerDocumentScrollMetrics,
): ImageFrameVirtualizationScrollMetrics {
  return {
    scrollPageOffset: metrics.scrollPageOffset,
    scrollTop: metrics.scrollTop,
    viewportHeight: metrics.viewportBlockSize,
  };
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";
import { type FrameDescriptor } from "@/lib/image-frame-source";
import {
  frameCssSize,
  frameIndexToNumber,
  type QuarterTurn,
} from "@/lib/image-geometry";

import { joinEffectKey } from "@/lib/effect-key";

export const IMAGE_FRAME_GAP = 16;
export const IMAGE_FRAME_PADDING = 16;
export const IMAGE_RENDER_FIT_PERFECTLY_OVERSCAN_PX =
  IMAGE_FRAME_GAP + IMAGE_FRAME_PADDING;
export const IMAGE_RENDER_WINDOW_OVERSCAN_PX = 1000;
export const IMAGE_VISIBLE_FRAME_OVERSCAN = 2;
export const IMAGE_PRELOAD_FRAME_OVERSCAN = 4;
export const IMAGE_SCROLL_REBASE_CONTAINER_PX = 12_000_000;
export const IMAGE_SCROLL_REBASE_TRIGGER_PX = 1_000_000;
export const IMAGE_SCROLL_REBASE_TARGET_PX = 2_000_000;
export const IMAGE_SCROLL_REBASE_TARGET_BOTTOM_PX =
  IMAGE_SCROLL_REBASE_CONTAINER_PX - IMAGE_SCROLL_REBASE_TARGET_PX;
export const IMAGE_SCROLL_REBASE_THRESHOLD_PX =
  IMAGE_SCROLL_REBASE_CONTAINER_PX - IMAGE_SCROLL_REBASE_TRIGGER_PX;

export type ImageFrameLayout = {
  frameIndex: number;
  frameNumber: number;
  width: number;
  height: number;
  offsetTop: number;
};

export type ImageFrameLayoutModel = {
  frameCount: number;
  gap: number;
  padding: number;
  totalHeight: number;
  maxFrameWidth: number;
  frames: readonly ImageFrameLayout[];
};

export type ImageRenderedFrameLayout = ImageFrameLayout & {
  windowTop: number;
};

export type ImageRenderedFrameWindow = {
  afterHeight: number;
  beforeHeight: number;
  frames: readonly ImageRenderedFrameLayout[];
  height: number;
  stickyInset: number;
};

export type ImageRenderPixelWindow = {
  bottom: number;
  top: number;
};

export type ImageScrollRebasePosition = {
  physicalScrollTop: number;
  scrollPageOffset: number;
};

export type ImageFrameVirtualizationScrollMetrics = {
  scrollPageOffset: number;
  scrollTop: number;
  viewportHeight: number;
};

type ImageFrameWindow = {
  scrollPageOffset: number;
  visibleFrameNumbers: readonly number[];
  renderFrameNumbers: readonly number[];
  preloadFrameNumbers: readonly number[];
};

export function createImageFrameLayout({
  frames,
  scale,
  rotation,
  gap = IMAGE_FRAME_GAP,
  padding = IMAGE_FRAME_PADDING,
}: {
  frames: readonly FrameDescriptor[];
  scale: number;
  rotation: QuarterTurn;
  gap?: number;
  padding?: number;
}): ImageFrameLayoutModel {
  // Vertical spacing scales with the image so the frame stack is a single
  // linear function of scale and the fit-width shell transform reproduces the
  // pre-toggle frame exactly. NOT rounded: frameCssSize leaves frame heights
  // fractional, so a rounded gap would desync the capture (old scale) from the
  // solve (new scale) at a retarget — exact scaling keeps gap / frame height
  // perfectly constant. The horizontal inline padding stays CONSTANT: the
  // returned `padding` field feeds `maxFrameWidth + padding × 2`, which must
  // keep equalling the available width at fit (the fit subtracts
  // IMAGE_VIEWER_HORIZONTAL_PADDING = padding × 2), or the stage would no
  // longer fill the viewport.
  const safeScale = Number.isFinite(scale) && scale > 0 ? scale : 1;
  const blockGap = gap * safeScale;
  const blockPadding = padding * safeScale;
  let offsetTop = blockPadding;
  let maxFrameWidth = 0;
  const frameLayouts = frames.map((frame, frameIndex) => {
    const frameRect = frameCssSize(frame.intrinsicSize, scale, rotation);
    const layout = {
      frameIndex,
      frameNumber: frameIndexToNumber(frameIndex),
      width: frameRect.width,
      height: frameRect.height,
      offsetTop,
    };
    offsetTop += frameRect.height + blockGap;
    maxFrameWidth = Math.max(maxFrameWidth, frameRect.width);
    return layout;
  });

  return {
    frameCount: frames.length,
    gap: blockGap,
    padding,
    totalHeight: frames.length === 0 ? 0 : offsetTop - blockGap + blockPadding,
    maxFrameWidth,
    frames: frameLayouts,
  };
}

export function getImageFrameLayout(
  layout: ImageFrameLayoutModel,
  frameNumber: number,
): ImageFrameLayout | undefined {
  if (!Number.isInteger(frameNumber)) return undefined;
  return layout.frames[frameNumber - 1];
}

export function findImageFrameByOffset(
  layout: ImageFrameLayoutModel,
  offset: number,
): number {
  if (layout.frameCount === 0) return 1;

  let low = 0;
  let high = layout.frames.length - 1;
  let match = 0;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (layout.frames[mid].offsetTop <= offset) {
      match = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return layout.frames[match].frameNumber;
}

export function getVisibleImageFrameNumbers({
  layout,
  scrollTop,
  viewportHeight,
  overscanFrames = IMAGE_VISIBLE_FRAME_OVERSCAN,
}: {
  layout: ImageFrameLayoutModel;
  scrollTop: number;
  viewportHeight: number;
  overscanFrames?: number;
}): readonly number[] {
  if (layout.frameCount === 0) return [];

  const measurementHeight = Math.max(1, viewportHeight);
  return getImageFrameNumbersInRange({
    layout,
    startOffset: Math.max(0, scrollTop - measurementHeight),
    endOffset: scrollTop + measurementHeight * 2,
    overscanFrames,
  });
}

export function getImageRenderFrameNumbers({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = IMAGE_RENDER_FIT_PERFECTLY_OVERSCAN_PX,
  layout,
  overscanPx = IMAGE_RENDER_WINDOW_OVERSCAN_PX,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  layout: ImageFrameLayoutModel;
  overscanPx?: number;
  scrollTop: number;
  viewportHeight: number;
}): readonly number[] {
  if (layout.frameCount === 0) return [];

  const window = createImageWindowFromScrollPosition({
    fitPerfectly,
    fitPerfectlyOverscanPx,
    overscanPx,
    scrollHeight: layout.totalHeight,
    scrollTop,
    viewportHeight,
  });

  return getImageFrameNumbersInRange({
    layout,
    startOffset: window.top,
    endOffset: window.bottom,
    overscanFrames: 0,
  });
}

export function getImagePreloadFrameNumbers({
  layout,
  renderFrameNumbers,
  overscanFrames = IMAGE_PRELOAD_FRAME_OVERSCAN,
}: {
  layout: ImageFrameLayoutModel;
  renderFrameNumbers: readonly number[];
  overscanFrames?: number;
}): readonly number[] {
  if (layout.frameCount === 0 || renderFrameNumbers.length === 0) return [];

  const firstRenderFrame = renderFrameNumbers[0];
  const lastRenderFrame = renderFrameNumbers[renderFrameNumbers.length - 1];
  return createFrameNumberRange(
    Math.max(1, firstRenderFrame - overscanFrames),
    Math.min(layout.frameCount, lastRenderFrame + overscanFrames),
  );
}

export function getImageRenderedFrameWindow({
  frameNumbers,
  layout,
  physicalScrollHeight = layout.totalHeight,
  scrollPageOffset = 0,
  viewportHeight,
}: {
  frameNumbers: readonly number[];
  layout: ImageFrameLayoutModel;
  physicalScrollHeight?: number;
  scrollPageOffset?: number;
  viewportHeight: number;
}): ImageRenderedFrameWindow | null {
  const frames = frameNumbers
    .map((frameNumber) => getImageFrameLayout(layout, frameNumber))
    .filter((frame): frame is ImageFrameLayout => Boolean(frame))
    .sort((left, right) => left.frameNumber - right.frameNumber);

  if (frames.length === 0) return null;

  const logicalBeforeHeight = frames[0].offsetTop;
  const windowBottom = Math.max(
    ...frames.map((frame) => frame.offsetTop + frame.height),
  );
  const height = Math.max(0, windowBottom - logicalBeforeHeight);
  const beforeHeight = getImagePagedLayoutTop({
    logicalTop: logicalBeforeHeight,
    scrollPageOffset,
    totalHeight: layout.totalHeight,
    viewportHeight,
  });
  const safeViewportHeight =
    Number.isFinite(viewportHeight) && viewportHeight > 0 ? viewportHeight : 0;
  const safePhysicalScrollHeight = Math.max(
    0,
    finiteNumber(physicalScrollHeight),
  );
  const stickyInset =
    safeViewportHeight > 0 ? -Math.max(0, height - safeViewportHeight) : 0;

  return {
    afterHeight: Math.max(0, safePhysicalScrollHeight - beforeHeight - height),
    beforeHeight,
    frames: frames.map((frame) => ({
      ...frame,
      windowTop: frame.offsetTop - logicalBeforeHeight,
    })),
    height,
    stickyInset,
  };
}

export function createImageWindowFromScrollPosition({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = 0,
  overscanPx,
  scrollHeight,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  overscanPx: number;
  scrollHeight: number;
  scrollTop: number;
  viewportHeight: number;
}): ImageRenderPixelWindow {
  const safeOverscanPx = safePadding(overscanPx);
  const safeScrollHeight = Math.max(0, finiteNumber(scrollHeight));
  const safeScrollTop = Math.max(0, finiteNumber(scrollTop));
  const safeViewportHeight = Math.max(0, finiteNumber(viewportHeight));
  const windowHeight = safeViewportHeight + safeOverscanPx * 2;
  const fitPerfectlyOverscan = safePadding(fitPerfectlyOverscanPx);
  const effectiveHeight = fitPerfectly
    ? safeViewportHeight + fitPerfectlyOverscan * 2
    : windowHeight;

  if (windowHeight >= safeScrollHeight || fitPerfectly) {
    const fitScrollTop = Math.min(safeScrollTop, safeScrollHeight);
    const top = Math.max(fitScrollTop - fitPerfectlyOverscan, 0);
    const bottom = Math.min(fitScrollTop + effectiveHeight, safeScrollHeight);
    return {
      bottom: Math.ceil(Math.max(bottom, top)),
      top: Math.floor(Math.max(0, top)),
    };
  }

  const scrollCenter = safeScrollTop + safeViewportHeight / 2;
  let top = scrollCenter - windowHeight / 2;
  let bottom = top + windowHeight;

  if (top < 0) {
    top = 0;
    bottom = windowHeight;
  }
  if (bottom > safeScrollHeight) {
    bottom = safeScrollHeight;
    top = safeScrollHeight - windowHeight;
  }

  return {
    bottom: Math.ceil(Math.max(bottom, top)),
    top: Math.floor(Math.max(0, top)),
  };
}

export function getImagePhysicalScrollHeight({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  const safeTotalHeight = safeSize(totalHeight);
  return shouldRebaseImageScroll({
    totalHeight: safeTotalHeight,
    viewportHeight,
  })
    ? Math.min(safeTotalHeight, IMAGE_SCROLL_REBASE_CONTAINER_PX)
    : safeTotalHeight;
}

export function getImageLogicalScrollTop({
  physicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  physicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    finiteNumber(physicalScrollTop) + safePadding(scrollPageOffset),
    0,
    getImageMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );
}

export function resolveImagePhysicalScrollPosition({
  logicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}): ImageScrollRebasePosition {
  const safeLogicalScrollTop = clamp(
    finiteNumber(logicalScrollTop),
    0,
    getImageMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );

  if (!shouldRebaseImageScroll({ totalHeight, viewportHeight })) {
    return {
      physicalScrollTop: clamp(
        safeLogicalScrollTop,
        0,
        getImageMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
      ),
      scrollPageOffset: 0,
    };
  }

  const currentPageOffset = clampImageScrollPageOffset({
    scrollPageOffset,
    totalHeight,
    viewportHeight,
  });
  const physicalScrollTop = safeLogicalScrollTop - currentPageOffset;
  const maxPhysicalScrollTop = getImageMaxPhysicalScrollTop({
    totalHeight,
    viewportHeight,
  });
  const maxPageOffset = getImageMaxScrollPageOffset({
    totalHeight,
    viewportHeight,
  });
  const shouldMoveDown =
    physicalScrollTop > IMAGE_SCROLL_REBASE_THRESHOLD_PX &&
    currentPageOffset < maxPageOffset;
  const shouldMoveUp =
    physicalScrollTop < IMAGE_SCROLL_REBASE_TRIGGER_PX && currentPageOffset > 0;

  if (
    physicalScrollTop < 0 ||
    physicalScrollTop > maxPhysicalScrollTop ||
    shouldMoveDown ||
    shouldMoveUp
  ) {
    return resolveImageScrollPageWindow({
      logicalScrollTop: safeLogicalScrollTop,
      preferredPhysicalScrollTop: shouldMoveUp
        ? Math.min(IMAGE_SCROLL_REBASE_TARGET_BOTTOM_PX, maxPhysicalScrollTop)
        : IMAGE_SCROLL_REBASE_TARGET_PX,
      totalHeight,
      viewportHeight,
    });
  }

  return {
    physicalScrollTop: roundImageScrollPixel(
      clamp(physicalScrollTop, 0, maxPhysicalScrollTop),
    ),
    scrollPageOffset: currentPageOffset,
  };
}

export function getImagePagedLayoutTop({
  logicalTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  if (!shouldRebaseImageScroll({ totalHeight, viewportHeight })) {
    return finiteNumber(logicalTop);
  }
  return Math.max(0, finiteNumber(logicalTop) - safePadding(scrollPageOffset));
}

export function getCurrentImageFrameNumber({
  layout,
  scrollTop,
  viewportHeight,
}: {
  layout: ImageFrameLayoutModel;
  scrollTop: number;
  viewportHeight: number;
}): number {
  return findImageFrameByOffset(layout, scrollTop + viewportHeight * 0.2);
}

export function useImageFrameVirtualization({
  freezeWindow = false,
  getScrollMetrics,
  layout,
  resetKey,
  sourceResetKey,
  viewportElement,
}: {
  freezeWindow?: boolean;
  getScrollMetrics?: () => ImageFrameVirtualizationScrollMetrics;
  layout: ImageFrameLayoutModel;
  resetKey?: unknown;
  // Identity of the underlying source. `resetKey` changes on every re-fit
  // (scale), but only a `sourceResetKey` change is a genuine new document that
  // should snap the window back to the top; a re-fit preserves the reading
  // position, so its window is re-derived from the live scroll instead.
  sourceResetKey?: unknown;
  viewportElement: HTMLDivElement | null;
}) {
  const resolvedSourceResetKey =
    sourceResetKey === undefined ? resetKey : sourceResetKey;
  const measureFrameRef = React.useRef(0);
  const hasMeasuredScrollRef = React.useRef(false);
  const lastMeasuredSourceResetKeyRef = React.useRef<unknown>(
    resolvedSourceResetKey,
  );
  const lastMeasuredScrollTopRef = React.useRef(0);
  const getCurrentScrollMetrics =
    React.useCallback((): ImageFrameVirtualizationScrollMetrics => {
      const sourceMatches = Object.is(
        lastMeasuredSourceResetKeyRef.current,
        resolvedSourceResetKey,
      );
      const metrics =
        sourceMatches && getScrollMetrics
          ? getScrollMetrics()
          : {
              scrollPageOffset: 0,
              scrollTop: sourceMatches ? (viewportElement?.scrollTop ?? 0) : 0,
              viewportHeight: viewportElement?.clientHeight ?? 0,
            };
      return reconcileImageScrollMetricsWithViewport(metrics, viewportElement);
    }, [getScrollMetrics, resolvedSourceResetKey, viewportElement]);
  const getFrameWindow = React.useCallback(
    (
      metrics: ImageFrameVirtualizationScrollMetrics,
      fitPerfectly = false,
    ): ImageFrameWindow => {
      const renderFrameNumbers = getImageRenderFrameNumbers({
        fitPerfectly,
        layout,
        scrollTop: metrics.scrollTop,
        viewportHeight: metrics.viewportHeight,
      });

      return {
        scrollPageOffset: metrics.scrollPageOffset,
        visibleFrameNumbers: getVisibleImageFrameNumbers({
          layout,
          scrollTop: metrics.scrollTop,
          viewportHeight: metrics.viewportHeight,
        }),
        renderFrameNumbers,
        preloadFrameNumbers: getImagePreloadFrameNumbers({
          layout,
          renderFrameNumbers,
        }),
      };
    },
    [layout],
  );
  const getCurrentVisibleFrameNumbers =
    React.useCallback((): ImageFrameWindow => {
      return getFrameWindow(getCurrentScrollMetrics());
    }, [getCurrentScrollMetrics, getFrameWindow]);
  const getResetFrameWindow = React.useCallback(() => {
    const viewportHeight = viewportElement?.clientHeight ?? 0;
    const renderFrameNumbers = getImageRenderFrameNumbers({
      layout,
      scrollTop: 0,
      viewportHeight,
    });

    return {
      scrollPageOffset: 0,
      visibleFrameNumbers: getVisibleImageFrameNumbers({
        layout,
        scrollTop: 0,
        viewportHeight,
      }),
      renderFrameNumbers,
      preloadFrameNumbers: getImagePreloadFrameNumbers({
        layout,
        renderFrameNumbers,
      }),
    };
  }, [layout, viewportElement]);
  const [state, setState] = React.useState<{
    layout: ImageFrameLayoutModel;
    resetKey: unknown;
    sourceResetKey: unknown;
    frameWindow: ImageFrameWindow;
  }>(() => ({
    layout,
    resetKey,
    sourceResetKey: resolvedSourceResetKey,
    frameWindow: getCurrentVisibleFrameNumbers(),
  }));
  const frameWindow =
    // While frozen (sidebar transition), keep the last committed window even
    // when the re-fit changes the layout/resetKey, so the same reading frames
    // stay mounted through the slide and settle rather than re-deriving from
    // the transient top-of-document scroll position.
    freezeWindow ||
    (Object.is(state.layout, layout) && Object.is(state.resetKey, resetKey))
      ? state.frameWindow
      : // Snap to the top only for a genuine new document; a re-fit (same
        // source, changed layout) preserves the reading position, so re-derive
        // its window from the live scroll rather than resetting to the top.
        Object.is(state.sourceResetKey, resolvedSourceResetKey)
        ? getCurrentVisibleFrameNumbers()
        : getResetFrameWindow();

  const measureVisibleFramesNow = React.useCallback(() => {
    measureFrameRef.current = 0;
    // While the sidebar slide freezes the layout, the scroll container reports
    // a transient top-of-document position, so re-deriving the visible-frame
    // window here would window to the top and rebase the reading frame at
    // settle. Hold the pre-slide window until the transition is idle again.
    if (freezeWindow) return;
    const metrics = getCurrentScrollMetrics();
    const fitPerfectly = shouldFitImagePerfectly({
      canFitPerfectly:
        hasMeasuredScrollRef.current &&
        Object.is(
          lastMeasuredSourceResetKeyRef.current,
          resolvedSourceResetKey,
        ),
      previousScrollTop: lastMeasuredScrollTopRef.current,
      scrollTop: metrics.scrollTop,
      viewportHeight: metrics.viewportHeight,
    });
    const nextFrameWindow = getFrameWindow(metrics, fitPerfectly);
    lastMeasuredSourceResetKeyRef.current = resolvedSourceResetKey;
    lastMeasuredScrollTopRef.current = metrics.scrollTop;
    hasMeasuredScrollRef.current = true;
    setState((previousState) =>
      Object.is(previousState.layout, layout) &&
      Object.is(previousState.resetKey, resetKey) &&
      areFrameWindowsEqual(previousState.frameWindow, nextFrameWindow)
        ? previousState
        : {
            layout,
            resetKey,
            sourceResetKey: resolvedSourceResetKey,
            frameWindow: nextFrameWindow,
          },
    );
    if (fitPerfectly && measureFrameRef.current === 0) {
      measureFrameRef.current = requestAnimationFrame(() =>
        measureVisibleFramesNowRef.current(),
      );
    }
  }, [
    freezeWindow,
    getCurrentScrollMetrics,
    getFrameWindow,
    layout,
    resetKey,
    resolvedSourceResetKey,
  ]);
  const measureVisibleFramesNowRef = React.useRef(measureVisibleFramesNow);
  useKeyedLayoutEffect(joinEffectKey([measureVisibleFramesNow]), () => {
    measureVisibleFramesNowRef.current = measureVisibleFramesNow;
  });

  const measureVisibleFrames = React.useCallback(() => {
    if (measureFrameRef.current) return;
    measureFrameRef.current = requestAnimationFrame(() =>
      measureVisibleFramesNowRef.current(),
    );
  }, []);

  useKeyedMountEffect(
    joinEffectKey(["image-virtualization-measure", measureVisibleFramesNow]),
    () => {
      if (measureFrameRef.current) {
        cancelAnimationFrame(measureFrameRef.current);
        measureFrameRef.current = 0;
      }
      measureVisibleFramesNow();
    },
  );

  // When the sidebar transition finishes and the freeze lifts, the reading
  // position has just been rebased by a settle scroll that may not have landed
  // in the same commit as this idle edge. Schedule a deferred re-measure so the
  // held window collapses back to the clean live window off the settled scroll;
  // without this the post-cycle mounted-frame set can differ from the pre-cycle
  // set (cycle-invariance "changed").
  const wasFrozenRef = React.useRef(freezeWindow);
  useKeyedLayoutEffect(joinEffectKey(["image-freeze-edge", freezeWindow]), () => {
    const wasFrozen = wasFrozenRef.current;
    wasFrozenRef.current = freezeWindow;
    if (wasFrozen && !freezeWindow) {
      measureVisibleFrames();
    }
  });

  useMountEffect(() => {
    return () => {
      if (measureFrameRef.current) {
        cancelAnimationFrame(measureFrameRef.current);
      }
    };
  });

  return {
    scrollPageOffset: frameWindow.scrollPageOffset,
    visibleFrameNumbers: frameWindow.visibleFrameNumbers,
    renderFrameNumbers: frameWindow.renderFrameNumbers,
    preloadFrameNumbers: frameWindow.preloadFrameNumbers,
    measureVisibleFrames,
  };
}

// On the cold path the document scroll model can momentarily report a
// top-of-document scrollTop while the viewport is actually scrolled deep, which
// would clobber the reading-frame window with the top window and then sit there
// (a stable-but-wrong state the benchmark's stability wait accepts). When the
// scroll is not page-rebased (no page offset) the logical scrollTop must equal
// the live DOM scrollTop, so trust the viewport if the metrics disagree at top.
function reconcileImageScrollMetricsWithViewport(
  metrics: ImageFrameVirtualizationScrollMetrics,
  viewportElement: HTMLDivElement | null,
): ImageFrameVirtualizationScrollMetrics {
  if (!viewportElement || metrics.scrollPageOffset !== 0) return metrics;
  const domScrollTop = viewportElement.scrollTop;
  if (domScrollTop > metrics.scrollTop + 1) {
    return { ...metrics, scrollTop: domScrollTop };
  }
  return metrics;
}

function getImageFrameNumbersInRange({
  layout,
  startOffset,
  endOffset,
  overscanFrames,
}: {
  layout: ImageFrameLayoutModel;
  startOffset: number;
  endOffset: number;
  overscanFrames: number;
}) {
  const safeStartOffset = Math.max(0, startOffset);
  const safeEndOffset = Math.max(safeStartOffset, endOffset);
  const firstVisibleFrame = findImageFrameByOffset(layout, safeStartOffset);
  const lastVisibleFrame = findImageFrameByOffset(layout, safeEndOffset);
  const firstFrame = Math.max(1, firstVisibleFrame - overscanFrames);
  const lastFrame = Math.min(
    layout.frameCount,
    lastVisibleFrame + overscanFrames,
  );

  return createFrameNumberRange(firstFrame, lastFrame);
}

function createFrameNumberRange(firstFrame: number, lastFrame: number) {
  if (lastFrame < firstFrame) return [];

  return Array.from(
    { length: lastFrame - firstFrame + 1 },
    (_, index) => firstFrame + index,
  );
}

function shouldRebaseImageScroll({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return (
    getImageMaxLogicalScrollTop({ totalHeight, viewportHeight }) >
    IMAGE_SCROLL_REBASE_THRESHOLD_PX
  );
}

function getImageMaxLogicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    safeSize(totalHeight) - Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getImageMaxPhysicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getImagePhysicalScrollHeight({ totalHeight, viewportHeight }) -
      Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getImageMaxScrollPageOffset({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getImageMaxLogicalScrollTop({ totalHeight, viewportHeight }) -
      getImageMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    0,
  );
}

function clampImageScrollPageOffset({
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    safePadding(scrollPageOffset),
    0,
    getImageMaxScrollPageOffset({ totalHeight, viewportHeight }),
  );
}

function resolveImageScrollPageWindow({
  logicalScrollTop,
  preferredPhysicalScrollTop,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  preferredPhysicalScrollTop: number;
  totalHeight: number;
  viewportHeight: number;
}): ImageScrollRebasePosition {
  let physicalScrollTop = roundImageScrollPixel(
    clamp(
      finiteNumber(preferredPhysicalScrollTop),
      0,
      getImageMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  let scrollPageOffset = clampImageScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  physicalScrollTop = roundImageScrollPixel(
    clamp(
      logicalScrollTop - scrollPageOffset,
      0,
      getImageMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  scrollPageOffset = clampImageScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  return { physicalScrollTop, scrollPageOffset };
}

function shouldFitImagePerfectly({
  canFitPerfectly,
  previousScrollTop,
  scrollTop,
  viewportHeight,
}: {
  canFitPerfectly: boolean;
  previousScrollTop: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  return (
    canFitPerfectly &&
    viewportHeight > 0 &&
    Math.abs(scrollTop - previousScrollTop) >
      viewportHeight + IMAGE_RENDER_WINDOW_OVERSCAN_PX * 2
  );
}

function areFrameWindowsEqual(
  previousFrameWindow: ImageFrameWindow,
  nextFrameWindow: ImageFrameWindow,
): boolean {
  return (
    previousFrameWindow.scrollPageOffset === nextFrameWindow.scrollPageOffset &&
    areFrameNumbersEqual(
      previousFrameWindow.visibleFrameNumbers,
      nextFrameWindow.visibleFrameNumbers,
    ) &&
    areFrameNumbersEqual(
      previousFrameWindow.renderFrameNumbers,
      nextFrameWindow.renderFrameNumbers,
    ) &&
    areFrameNumbersEqual(
      previousFrameWindow.preloadFrameNumbers,
      nextFrameWindow.preloadFrameNumbers,
    )
  );
}

function finiteNumber(value: number) {
  return Number.isFinite(value) ? value : 0;
}

function roundImageScrollPixel(value: number) {
  if (typeof window === "undefined") return Math.round(value);
  const ratio = window.devicePixelRatio || 1;
  return Math.round(value * ratio) / ratio;
}

function safePadding(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function safeSize(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function areFrameNumbersEqual(
  previousFrameNumbers: readonly number[],
  nextFrameNumbers: readonly number[],
): boolean {
  if (previousFrameNumbers.length !== nextFrameNumbers.length) return false;
  return previousFrameNumbers.every(
    (frameNumber, index) => frameNumber === nextFrameNumbers[index],
  );
}

"use client";

import * as React from "react";
import { createRoot, type Root } from "react-dom/client";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";
import {
  ImageSourceDisposedError,
  toImageFormatError,
  type FrameSource,
} from "@/lib/image-frame-source";
import {
  frameCssSize,
  frameIndexToNumber,
  type FrameOverlayProps,
  type QuarterTurn,
} from "@/lib/image-geometry";
import { isResourceError } from "@/lib/viewer-errors";
import {
  type ImageFrameRenderTiming,
  type ImageViewerProps,
} from "@/components/ui/image-viewer-types";
import { ScrollArea } from "@/components/ui/scroll-area";

import {
  getImageFrameLayout,
  getImagePhysicalScrollHeight,
  getImageRenderedFrameWindow,
  useImageFrameVirtualization,
  type ImageFrameLayout,
  type ImageFrameLayoutModel,
  type ImageFrameVirtualizationScrollMetrics,
  type ImageRenderedFrameLayout,
  type ImageRenderedFrameWindow,
} from "./image-viewer-virtualization";
import { joinEffectKey } from "@/lib/effect-key";

const IMAGE_SCROLL_IDLE_MS = 120;
const IMAGE_RETAINED_DECODED_PIXEL_BUDGET = 24_000_000;
const IMAGE_RETAINED_RENDERED_PIXEL_BUDGET = 32_000_000;
const IMAGE_FRAME_RENDER_CONCURRENCY = 4;
const IMAGE_LOW_PRIORITY_FRAME_RENDER_CONCURRENCY = 1;

type ImageRenderQuality = "high" | "low";

export interface ImageFrameProps {
  source: FrameSource;
  frameIndex: number;
  scale: number;
  rasterScale?: number;
  rotation: QuarterTurn;
  renderQuality?: ImageRenderQuality;
  renderOverlay?: (props: FrameOverlayProps) => React.ReactNode;
  onFrameRenderTiming?: (timing: ImageFrameRenderTiming) => void;
}

type ImageProjectionCallback = NonNullable<
  | ImageViewerProps["onFrameRenderTiming"]
  | ImageViewerProps["renderFrameOverlay"]
>;

export interface ImageFrameScrollerProps {
  source: FrameSource;
  layout: ImageFrameLayoutModel;
  scale: number;
  rotation: QuarterTurn;
  documentSurfaceRef?: React.Ref<HTMLDivElement>;
  frameListRef: React.Ref<HTMLDivElement>;
  getScrollMetrics?: () => ImageFrameVirtualizationScrollMetrics;
  freezeVisibleFrameWindow?: boolean;
  viewportRef: React.Ref<HTMLDivElement>;
  onScroll: () => void;
  renderFrameOverlay?: ImageViewerProps["renderFrameOverlay"];
  onFrameRenderTiming?: ImageViewerProps["onFrameRenderTiming"];
}

export function ImageFrame({
  source,
  frameIndex,
  scale,
  rasterScale = scale,
  rotation,
  renderQuality = "high",
  renderOverlay,
  onFrameRenderTiming,
}: ImageFrameProps) {
  const descriptor = source.frames[frameIndex];
  const frameRect = frameCssSize(descriptor.intrinsicSize, scale, rotation);
  const frameNumber = frameIndexToNumber(frameIndex);

  return (
    <div
      className="ring-border relative shadow-sm ring-1"
      style={{ width: frameRect.width, height: frameRect.height }}
      data-slot="image-frame"
      data-frame={frameNumber}
      data-frame-number={frameNumber}
    >
      <ImageFrameCanvas
        source={source}
        frameIndex={frameIndex}
        layoutScale={scale}
        rasterScale={rasterScale}
        rotation={rotation}
        renderQuality={renderQuality}
        onFrameRenderTiming={onFrameRenderTiming}
      />
      {renderOverlay ? (
        <div className="pointer-events-none absolute inset-0">
          {renderOverlay({
            frameNumber,
            frameRect,
            scale,
            rotation,
          })}
        </div>
      ) : null}
    </div>
  );
}

function ImageFrameCanvas({
  source,
  frameIndex,
  layoutScale,
  rasterScale,
  rotation,
  renderQuality,
  onFrameRenderTiming,
}: {
  source: FrameSource;
  frameIndex: number;
  layoutScale: number;
  rasterScale: number;
  rotation: QuarterTurn;
  renderQuality: ImageRenderQuality;
  onFrameRenderTiming?: (timing: ImageFrameRenderTiming) => void;
}) {
  const descriptor = source.frames[frameIndex];
  const dpr = getImageDevicePixelRatio();
  const layoutFrameRect = frameCssSize(
    descriptor.intrinsicSize,
    layoutScale,
    rotation,
  );
  const rasterFrameRect = frameCssSize(
    descriptor.intrinsicSize,
    rasterScale,
    rotation,
  );
  const [drawError, setDrawError] = React.useState<Error | null>(null);

  if (drawError) throw drawError;

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const canvasWidth = Math.max(1, Math.floor(rasterFrameRect.width * dpr));
      const canvasHeight = Math.max(
        1,
        Math.floor(rasterFrameRect.height * dpr),
      );
      const cached = source.hasDecodedFrame(frameIndex);
      const previousCanvas = resizeImageCanvas(
        canvas,
        canvasWidth,
        canvasHeight,
        { preserve: !cached },
      );
      if (previousCanvas) {
        preserveCanvasImage(ctx, previousCanvas, canvasWidth, canvasHeight);
      }

      let cancelled = false;
      let settled = false;
      let reported = false;
      const startedAt = now();
      const renderScale = rasterScale * dpr;
      const report = (status: ImageFrameRenderTiming["status"]) => {
        if (reported) return;
        reported = true;
        notifyImageFrameRenderTiming(onFrameRenderTiming, {
          cached,
          durationMs: now() - startedAt,
          frameNumber: frameIndexToNumber(frameIndex),
          pixelRatio: dpr,
          renderScale,
          status,
        });
      };
      source
        .acquire(frameIndex)
        .then((bitmap) => {
          settled = true;
          if (cancelled) return;
          ctx.save();
          try {
            ctx.scale(dpr, dpr);
            ctx.translate(rasterFrameRect.width / 2, rasterFrameRect.height / 2);
            ctx.rotate((rotation * Math.PI) / 180);
            const drawWidth = descriptor.intrinsicSize.width * rasterScale;
            const drawHeight = descriptor.intrinsicSize.height * rasterScale;
            ctx.imageSmoothingQuality = renderQuality;
            ctx.drawImage(
              bitmap,
              -drawWidth / 2,
              -drawHeight / 2,
              drawWidth,
              drawHeight,
            );
            canvas.dataset.imageFrameRendered = "true";
          } finally {
            ctx.restore();
          }
          report("rendered");
        })
        .catch((error) => {
          settled = true;
          if (error instanceof ImageSourceDisposedError) return;
          if (!cancelled) {
            report("failed");
            setDrawError(
              isResourceError(error)
                ? error
                : toImageFormatError(error, {
                    kind: "decode_failed",
                    message: "Image decode failed",
                  }),
            );
          }
        });

      return () => {
        cancelled = true;
        if (!settled) report("cancelled");
        source.release(frameIndex);
      };
    },
    [
      descriptor.intrinsicSize.height,
      descriptor.intrinsicSize.width,
      dpr,
      frameIndex,
      onFrameRenderTiming,
      rasterFrameRect.height,
      rasterFrameRect.width,
      rasterScale,
      renderQuality,
      rotation,
      source,
    ],
  );

  return (
    <canvas
      ref={canvasRef}
      style={{ width: layoutFrameRect.width, height: layoutFrameRect.height }}
      className="block bg-white"
    />
  );
}

export function ImageFrameScroller({
  source,
  layout,
  scale,
  rotation,
  documentSurfaceRef,
  frameListRef,
  getScrollMetrics,
  freezeVisibleFrameWindow = false,
  viewportRef,
  onScroll,
  renderFrameOverlay,
  onFrameRenderTiming,
}: ImageFrameScrollerProps) {
  const canvasRef = React.useRef<HTMLDivElement | null>(null);
  const projectionFrameRef = React.useRef<number | null>(null);
  const idleTimerRef = React.useRef<number | null>(null);
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null);
  const [viewportElement, setViewportElement] =
    React.useState<HTMLDivElement | null>(null);
  const projectionCacheRef = React.useRef<ImageFrameProjectionCache>({
    clock: 0,
    frames: new Map(),
    resetKey: "",
  });
  const scrollStateRef = React.useRef({
    isScrolling: false,
  });
  const sourceKey = getImageProjectionSourceKey(source);
  const layoutResetKey = [
    sourceKey,
    layout.frameCount,
    layout.maxFrameWidth,
    layout.totalHeight,
    scale,
    rotation,
  ].join("\u0000");
  const projectionResetKey = String(sourceKey);
  const {
    scrollPageOffset,
    visibleFrameNumbers,
    renderFrameNumbers,
    preloadFrameNumbers,
    measureVisibleFrames,
  } = useImageFrameVirtualization({
    freezeWindow: freezeVisibleFrameWindow,
    getScrollMetrics,
    layout,
    resetKey: layoutResetKey,
    sourceResetKey: projectionResetKey,
    viewportElement,
  });
  const viewportHeight = viewportElement?.clientHeight ?? 0;
  const physicalScrollHeight = getImagePhysicalScrollHeight({
    totalHeight: layout.totalHeight,
    viewportHeight,
  });
  const documentInlineSize = layout.maxFrameWidth + layout.padding * 2;
  const renderedWindow = React.useMemo(
    () =>
      getImageRenderedFrameWindow({
        frameNumbers: renderFrameNumbers,
        layout,
        physicalScrollHeight,
        scrollPageOffset,
        viewportHeight,
      }),
    [
      layout,
      physicalScrollHeight,
      renderFrameNumbers,
      scrollPageOffset,
      viewportHeight,
    ],
  );
  const imageDevicePixelRatio = getImageDevicePixelRatio();
  const lowPriorityFrameNumbers = React.useMemo(
    () => [...renderFrameNumbers, ...preloadFrameNumbers],
    [preloadFrameNumbers, renderFrameNumbers],
  );
  const {
    activeFrameNumbers,
    onFrameRenderTiming: handleScheduledFrameRenderTiming,
  } = useImageFrameRenderScheduler({
    frameNumbers: visibleFrameNumbers,
    lowPriorityFrameNumbers,
    scale,
    rotation,
    pixelRatio: imageDevicePixelRatio,
    resetKey: layoutResetKey,
    maxRunning: IMAGE_FRAME_RENDER_CONCURRENCY,
    maxLowPriorityRunning: IMAGE_LOW_PRIORITY_FRAME_RENDER_CONCURRENCY,
  });
  const handleFrameRenderTiming = React.useCallback(
    (timing: ImageFrameRenderTiming) => {
      handleScheduledFrameRenderTiming(timing);
      onFrameRenderTiming?.(timing);
    },
    [handleScheduledFrameRenderTiming, onFrameRenderTiming],
  );

  const projectFrames = React.useCallback(() => {
    projectionFrameRef.current = null;
    projectImageFrames({
      activeFrameNumbers,
      cache: projectionCacheRef.current,
      canvas: canvasRef.current,
      layout,
      onFrameRenderTiming: handleFrameRenderTiming,
      preloadFrameNumbers,
      renderFrameOverlay,
      renderQuality: scrollStateRef.current.isScrolling ? "low" : "high",
      renderedWindow,
      renderFrameNumbers,
      resetKey: projectionResetKey,
      rotation,
      scale,
      shouldHoldRaster: freezeVisibleFrameWindow,
      source,
      sourceKey,
      visibleFrameNumbers,
    });
  }, [
    activeFrameNumbers,
    handleFrameRenderTiming,
    layout,
    preloadFrameNumbers,
    projectionResetKey,
    renderFrameOverlay,
    renderedWindow,
    renderFrameNumbers,
    rotation,
    scale,
    freezeVisibleFrameWindow,
    source,
    sourceKey,
    visibleFrameNumbers,
  ]);
  const projectFramesRef = React.useRef(projectFrames);
  useKeyedLayoutEffect(joinEffectKey([projectFrames]), () => {
    projectFramesRef.current = projectFrames;
  });

  const scheduleProjectFrames = React.useCallback(() => {
    if (projectionFrameRef.current !== null) return;
    if (typeof requestAnimationFrame !== "function") {
      projectFramesRef.current();
      return;
    }
    projectionFrameRef.current = requestAnimationFrame(() => {
      projectFramesRef.current();
    });
  }, []);

  useKeyedMountEffect(joinEffectKey(["image-project", projectFrames]), () => {
    projectFrames();
  });

  // Commit-then-relax: a re-fit commit (scale/layout/rotation change) must
  // project the frame boxes BEFORE paint — the shell motion transform is
  // computed for the settled layout, so stale boxes under it would paint one
  // mismatched frame. Scroll-driven window updates keep the deferred (rAF)
  // projection above.
  useKeyedLayoutEffect(
    joinEffectKey(["image-project-refit", layoutResetKey]),
    () => {
      projectFramesRef.current();
    },
  );

  useMountEffect(() => {
    return () => {
      if (
        projectionFrameRef.current !== null &&
        typeof cancelAnimationFrame === "function"
      ) {
        cancelAnimationFrame(projectionFrameRef.current);
      }
      if (idleTimerRef.current !== null) {
        window.clearTimeout(idleTimerRef.current);
      }
      disposeImageFrameProjectionCache(projectionCacheRef.current);
    };
  });

  const setViewportRef = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element;
      setViewportElement(element);
      assignImageRef(viewportRef, element);
    },
    [viewportRef],
  );

  const setCanvasRef = React.useCallback((element: HTMLDivElement | null) => {
    canvasRef.current = element;
  }, []);

  const handleScroll = React.useCallback(() => {
    onScroll();
    measureVisibleFrames();
    scrollStateRef.current.isScrolling = true;

    if (idleTimerRef.current !== null) {
      window.clearTimeout(idleTimerRef.current);
    }
    idleTimerRef.current = window.setTimeout(() => {
      idleTimerRef.current = null;
      scrollStateRef.current.isScrolling = false;
      scheduleProjectFrames();
    }, IMAGE_SCROLL_IDLE_MS);
  }, [measureVisibleFrames, onScroll, scheduleProjectFrames]);

  return (
    <ScrollArea
      className="min-h-0 flex-1"
      viewportRef={setViewportRef}
      viewportProps={{
        onScroll: handleScroll,
        style: { overflowAnchor: "none" },
      }}
    >
      <div
        ref={frameListRef}
        className="relative min-h-full w-full"
        data-slot="image-viewer-fit-width-measure"
      >
        <div
          ref={documentSurfaceRef}
          className="relative mx-auto"
          data-slot="image-viewer-document"
          style={{
            contain: "layout style",
            height: physicalScrollHeight,
            minWidth: documentInlineSize,
            width: documentInlineSize,
          }}
        >
          {renderedWindow ? (
            <>
              <div
                aria-hidden
                data-slot="image-frame-window-before"
                style={{
                  contain: "layout size",
                  height: renderedWindow.beforeHeight,
                }}
              />
              <div
                className="sticky"
                data-slot="image-frame-sticky-window"
                style={{
                  bottom: renderedWindow.stickyInset,
                  contain: "layout style inline-size",
                  height: renderedWindow.height,
                  isolation: "isolate",
                  top: renderedWindow.stickyInset,
                }}
              >
                <div
                  ref={setCanvasRef}
                  className="relative mx-auto h-full w-full"
                  data-slot="image-frame-virtual-canvas"
                  style={{
                    contain: "layout style",
                    height: renderedWindow.height,
                    minWidth: documentInlineSize,
                    width: documentInlineSize,
                  }}
                />
              </div>
              <div
                aria-hidden
                data-slot="image-frame-window-after"
                style={{
                  contain: "layout size",
                  height: renderedWindow.afterHeight,
                }}
              />
            </>
          ) : null}
        </div>
      </div>
    </ScrollArea>
  );
}

type ImageFrameProjectionCache = {
  clock: number;
  frames: Map<number, ProjectedImageFrame>;
  resetKey: string;
};

type ProjectedImageFrame = {
  decodedPixels: number;
  isLive: boolean;
  lastSeen: number;
  rasterScale: number | null;
  renderedPixels: number;
  renderKey: string;
  root: Root;
  shell: HTMLElement;
};

const imageProjectionSourceKeys = new WeakMap<FrameSource, number>();
const imageProjectionCallbackKeys = new WeakMap<
  ImageProjectionCallback,
  number
>();
let nextImageProjectionSourceKey = 1;
let nextImageProjectionCallbackKey = 1;

type ImageFrameRenderRequest = {
  frameNumber: number;
  pixelRatio: number;
  renderScale: number;
  rotation: QuarterTurn;
};

function useImageFrameRenderScheduler({
  frameNumbers,
  lowPriorityFrameNumbers = [],
  scale,
  rotation,
  pixelRatio,
  resetKey,
  maxRunning = IMAGE_FRAME_RENDER_CONCURRENCY,
  maxLowPriorityRunning = IMAGE_LOW_PRIORITY_FRAME_RENDER_CONCURRENCY,
}: {
  frameNumbers: readonly number[];
  lowPriorityFrameNumbers?: readonly number[];
  scale: number;
  rotation: QuarterTurn;
  pixelRatio: number;
  resetKey: unknown;
  maxRunning?: number;
  maxLowPriorityRunning?: number;
}) {
  const renderScale = scale * pixelRatio;
  const requestedRenders = React.useMemo<ImageFrameRenderRequest[]>(
    () =>
      mergeImageFrameNumbers(frameNumbers).map((frameNumber) => ({
        frameNumber,
        pixelRatio,
        renderScale,
        rotation,
      })),
    [frameNumbers, pixelRatio, renderScale, rotation],
  );
  const lowPriorityRequestedRenders = React.useMemo<
    ImageFrameRenderRequest[]
  >(() => {
    const primaryFrameNumberSet = new Set(frameNumbers);
    return mergeImageFrameNumbers(lowPriorityFrameNumbers)
      .filter((frameNumber) => !primaryFrameNumberSet.has(frameNumber))
      .map((frameNumber) => ({
        frameNumber,
        pixelRatio,
        renderScale,
        rotation,
      }));
  }, [
    frameNumbers,
    lowPriorityFrameNumbers,
    pixelRatio,
    renderScale,
    rotation,
  ]);
  const allRequestedRenders = React.useMemo(
    () => [...requestedRenders, ...lowPriorityRequestedRenders],
    [lowPriorityRequestedRenders, requestedRenders],
  );
  const requestedRendersRef = React.useRef(allRequestedRenders);
  const resetKeyRef = React.useRef(resetKey);
  const renderContextRef = React.useRef({ rotation });
  useKeyedLayoutEffect(
    joinEffectKey([allRequestedRenders, resetKey, rotation]),
    () => {
      requestedRendersRef.current = allRequestedRenders;
      resetKeyRef.current = resetKey;
      renderContextRef.current = { rotation };
    },
  );

  const [state, setState] = React.useState<{
    renderedByKey: ReadonlyMap<string, ImageFrameRenderRequest>;
    resetKey: unknown;
  }>(() => ({ renderedByKey: new Map(), resetKey }));
  const emptyRenderedByKey = React.useMemo<
    ReadonlyMap<string, ImageFrameRenderRequest>
  >(() => new Map(), []);
  const renderedByKey = Object.is(state.resetKey, resetKey)
    ? state.renderedByKey
    : emptyRenderedByKey;

  useKeyedMountEffect(joinEffectKey([allRequestedRenders, resetKey]), () => {
    setState((previousState) => {
      if (!Object.is(previousState.resetKey, resetKey)) {
        return { renderedByKey: new Map(), resetKey };
      }

      const renderedByKey = new Map<string, ImageFrameRenderRequest>();
      for (const [key, rendered] of previousState.renderedByKey) {
        if (
          allRequestedRenders.some((request) =>
            doesRenderedImageFrameSatisfyRequest(rendered, request),
          )
        ) {
          renderedByKey.set(key, rendered);
        }
      }

      return areImageRenderMapsEqual(previousState.renderedByKey, renderedByKey)
        ? previousState
        : { renderedByKey, resetKey };
    });
  });

  const activeFrameNumbers = React.useMemo(() => {
    const renderedFrameNumbers: number[] = [];
    const pendingFrameNumbers: number[] = [];
    const lowPriorityRenderedFrameNumbers: number[] = [];
    const lowPriorityPendingFrameNumbers: number[] = [];

    for (const request of requestedRenders) {
      if (isImageRenderRequestSatisfied(request, renderedByKey)) {
        renderedFrameNumbers.push(request.frameNumber);
      } else {
        pendingFrameNumbers.push(request.frameNumber);
      }
    }
    for (const request of lowPriorityRequestedRenders) {
      if (isImageRenderRequestSatisfied(request, renderedByKey)) {
        lowPriorityRenderedFrameNumbers.push(request.frameNumber);
      } else {
        lowPriorityPendingFrameNumbers.push(request.frameNumber);
      }
    }

    const activePrimaryFrameNumbers = [
      ...renderedFrameNumbers,
      ...pendingFrameNumbers.slice(0, Math.max(1, maxRunning)),
    ];
    const activeLowPriorityFrameNumbers =
      pendingFrameNumbers.length > 0
        ? lowPriorityRenderedFrameNumbers
        : [
            ...lowPriorityRenderedFrameNumbers,
            ...lowPriorityPendingFrameNumbers.slice(
              0,
              Math.max(0, maxLowPriorityRunning),
            ),
          ];

    return mergeImageFrameNumbers([
      ...activePrimaryFrameNumbers,
      ...activeLowPriorityFrameNumbers,
    ]);
  }, [
    lowPriorityRequestedRenders,
    maxLowPriorityRunning,
    maxRunning,
    renderedByKey,
    requestedRenders,
  ]);

  const onFrameRenderTiming = React.useCallback(
    (timing: ImageFrameRenderTiming) => {
      const rendered: ImageFrameRenderRequest = {
        frameNumber: timing.frameNumber,
        pixelRatio: timing.pixelRatio,
        renderScale: timing.renderScale,
        rotation: renderContextRef.current.rotation,
      };
      const key = getImageFrameRenderKey(rendered);

      setState((previousState) => {
        const resetKey = resetKeyRef.current;
        const previousRenderedByKey = Object.is(
          previousState.resetKey,
          resetKey,
        )
          ? previousState.renderedByKey
          : new Map<string, ImageFrameRenderRequest>();
        const nextRenderedByKey = new Map(previousRenderedByKey);

        if (
          timing.status === "rendered" &&
          requestedRendersRef.current.some((request) =>
            doesRenderedImageFrameSatisfyRequest(rendered, request),
          )
        ) {
          nextRenderedByKey.set(key, rendered);
        } else {
          nextRenderedByKey.delete(key);
        }

        return areImageRenderMapsEqual(previousRenderedByKey, nextRenderedByKey)
          ? previousState
          : { renderedByKey: nextRenderedByKey, resetKey };
      });
    },
    [],
  );

  return { activeFrameNumbers, onFrameRenderTiming };
}

function mergeImageFrameNumbers(frameNumbers: readonly number[]) {
  return [...new Set(frameNumbers)].sort((left, right) => left - right);
}

function getImageFrameRenderKey({
  frameNumber,
  pixelRatio,
  renderScale,
  rotation,
}: ImageFrameRenderRequest) {
  return `${frameNumber}:${renderScale}:${rotation}:${pixelRatio}`;
}

function isImageRenderRequestSatisfied(
  request: ImageFrameRenderRequest,
  renderedByKey: ReadonlyMap<string, ImageFrameRenderRequest>,
) {
  for (const rendered of renderedByKey.values()) {
    if (doesRenderedImageFrameSatisfyRequest(rendered, request)) return true;
  }
  return false;
}

function doesRenderedImageFrameSatisfyRequest(
  rendered: ImageFrameRenderRequest,
  request: ImageFrameRenderRequest,
) {
  return (
    rendered.frameNumber === request.frameNumber &&
    rendered.renderScale === request.renderScale &&
    rendered.rotation === request.rotation &&
    rendered.pixelRatio >= request.pixelRatio
  );
}

function areImageRenderMapsEqual(
  left: ReadonlyMap<string, ImageFrameRenderRequest>,
  right: ReadonlyMap<string, ImageFrameRenderRequest>,
) {
  if (left.size !== right.size) return false;
  for (const [key, value] of left) {
    if (right.get(key) !== value) return false;
  }
  return true;
}

function projectImageFrames({
  activeFrameNumbers,
  cache,
  canvas,
  layout,
  onFrameRenderTiming,
  preloadFrameNumbers,
  renderFrameOverlay,
  renderQuality,
  renderedWindow,
  renderFrameNumbers,
  resetKey,
  rotation,
  scale,
  shouldHoldRaster,
  source,
  sourceKey,
  visibleFrameNumbers,
}: {
  activeFrameNumbers: readonly number[];
  cache: ImageFrameProjectionCache;
  canvas: HTMLDivElement | null;
  layout: ImageFrameLayoutModel;
  onFrameRenderTiming?: ImageViewerProps["onFrameRenderTiming"];
  preloadFrameNumbers: readonly number[];
  renderFrameOverlay?: ImageViewerProps["renderFrameOverlay"];
  renderQuality: ImageRenderQuality;
  renderedWindow: ImageRenderedFrameWindow | null;
  renderFrameNumbers: readonly number[];
  resetKey: string;
  rotation: QuarterTurn;
  scale: number;
  shouldHoldRaster: boolean;
  source: FrameSource;
  sourceKey: number;
  visibleFrameNumbers: readonly number[];
}) {
  if (cache.resetKey !== resetKey) {
    disposeImageFrameProjectionCache(cache);
    cache.resetKey = resetKey;
  }
  if (!canvas || !renderedWindow) return;

  cache.clock += 1;
  const activeFrameNumberSet = new Set(activeFrameNumbers);
  const renderedFrameNumberSet = new Set(renderFrameNumbers);
  const visibleFrameNumberSet = new Set(visibleFrameNumbers);
  const activePreloadFrameNumbers = activeFrameNumbers.filter(
    (frameNumber) => !renderedFrameNumberSet.has(frameNumber),
  );
  const retainedFrameIndexes = new Set<number>();

  let previousShell: HTMLElement | null = null;
  for (const frame of renderedWindow.frames) {
    retainedFrameIndexes.add(frame.frameIndex);
    const existingFrame = cache.frames.get(frame.frameIndex);
    if (!existingFrame && !activeFrameNumberSet.has(frame.frameNumber))
      continue;
    const projectedFrame = existingFrame ?? createProjectedImageFrame(frame);
    projectedFrame.lastSeen = cache.clock;
    projectedFrame.decodedPixels = frameDecodedPixels(source, frame.frameIndex);
    projectedFrame.renderedPixels = frameRenderedPixels(frame);
    patchProjectedImageFrame({
      frame,
      isVisible: visibleFrameNumberSet.has(frame.frameNumber),
      shell: projectedFrame.shell,
    });
    if (activeFrameNumberSet.has(frame.frameNumber)) {
      const retainHeldRaster =
        shouldHoldRaster &&
        existingFrame != null &&
        existingFrame.rasterScale != null &&
        existingFrame.renderKey !== "";
      const rasterScale = retainHeldRaster
        ? existingFrame.rasterScale!
        : scale;
      renderProjectedImageFrame({
        frame,
        onFrameRenderTiming,
        projectedFrame,
        renderFrameOverlay,
        renderQuality,
        rasterScale,
        rotation,
        scale,
        source,
        sourceKey,
      });
    }
    cache.frames.set(frame.frameIndex, projectedFrame);
    placeProjectedImageFrame(canvas, projectedFrame.shell, previousShell);
    previousShell = projectedFrame.shell;
  }

  detachUnrenderedImageFrames(cache, retainedFrameIndexes);
  schedulePrefetchImageFrames({
    frameNumbers: activePreloadFrameNumbers,
    layout,
    source,
  });
  evictImageFrameProjectionCache(cache, retainedFrameIndexes);
}

function createProjectedImageFrame(
  frame: ImageRenderedFrameLayout,
): ProjectedImageFrame {
  const shell = document.createElement("div");
  shell.className = "absolute top-0 left-1/2";
  shell.dataset.slot = "image-frame-slot";
  shell.dataset.virtualFrameNumber = String(frame.frameNumber);

  return {
    decodedPixels: 0,
    isLive: true,
    lastSeen: 0,
    rasterScale: null,
    renderedPixels: 0,
    renderKey: "",
    root: createRoot(shell),
    shell,
  };
}

function patchProjectedImageFrame({
  frame,
  isVisible,
  shell,
}: {
  frame: ImageRenderedFrameLayout;
  isVisible: boolean;
  shell: HTMLElement;
}) {
  shell.dataset.virtualFrameNumber = String(frame.frameNumber);
  if (isVisible) {
    shell.dataset.visible = "";
  } else {
    delete shell.dataset.visible;
  }
  setImageStyle(shell, "transform", `translate(-50%, ${frame.windowTop}px)`);
  setImagePixelStyle(shell, "width", frame.width);
  setImagePixelStyle(shell, "height", frame.height);
}

function renderProjectedImageFrame({
  frame,
  onFrameRenderTiming,
  projectedFrame,
  renderFrameOverlay,
  renderQuality,
  rasterScale,
  rotation,
  scale,
  source,
  sourceKey,
}: {
  frame: ImageRenderedFrameLayout;
  onFrameRenderTiming?: ImageViewerProps["onFrameRenderTiming"];
  projectedFrame: ProjectedImageFrame;
  renderFrameOverlay?: ImageViewerProps["renderFrameOverlay"];
  renderQuality: ImageRenderQuality;
  rasterScale: number;
  rotation: QuarterTurn;
  scale: number;
  source: FrameSource;
  sourceKey: number;
}) {
  const renderKey = [
    frame.frameIndex,
    sourceKey,
    frame.width,
    frame.height,
    scale,
    rasterScale,
    rotation,
    renderQuality,
    getImageProjectionCallbackKey(renderFrameOverlay),
    getImageProjectionCallbackKey(onFrameRenderTiming),
    getImageDevicePixelRatio(),
  ].join("\u0000");

  projectedFrame.rasterScale = rasterScale;

  if (projectedFrame.renderKey === renderKey) return;
  projectedFrame.renderKey = renderKey;
  projectedFrame.root.render(
    <ImageFrame
      source={source}
      frameIndex={frame.frameIndex}
      scale={scale}
      rasterScale={rasterScale}
      rotation={rotation}
      renderQuality={renderQuality}
      onFrameRenderTiming={onFrameRenderTiming}
      renderOverlay={
        renderFrameOverlay
          ? ({ frameNumber, frameRect, scale, rotation }) =>
              renderFrameOverlay({
                frameNumber,
                width: frameRect.width,
                height: frameRect.height,
                scale,
                rotation,
              })
          : undefined
      }
    />,
  );
}

function placeProjectedImageFrame(
  canvas: HTMLElement,
  shell: HTMLElement,
  previousShell: HTMLElement | null,
) {
  const nextSibling = previousShell
    ? previousShell.nextSibling
    : canvas.firstChild;
  if (shell === nextSibling) return;
  canvas.insertBefore(shell, nextSibling);
}

function detachUnrenderedImageFrames(
  cache: ImageFrameProjectionCache,
  retainedFrameIndexes: ReadonlySet<number>,
) {
  for (const [frameIndex, frame] of cache.frames) {
    if (retainedFrameIndexes.has(frameIndex)) continue;
    frame.shell.remove();
  }
}

function evictImageFrameProjectionCache(
  cache: ImageFrameProjectionCache,
  visibleFrameIndexes: ReadonlySet<number>,
) {
  let decodedPixels = 0;
  let renderedPixels = 0;

  for (const frame of cache.frames.values()) {
    decodedPixels += frame.decodedPixels;
    renderedPixels += frame.renderedPixels;
  }

  if (
    decodedPixels <= IMAGE_RETAINED_DECODED_PIXEL_BUDGET &&
    renderedPixels <= IMAGE_RETAINED_RENDERED_PIXEL_BUDGET
  ) {
    return;
  }

  const evictableFrames = [...cache.frames.entries()]
    .filter(([frameIndex]) => !visibleFrameIndexes.has(frameIndex))
    .sort(([, a], [, b]) => a.lastSeen - b.lastSeen);

  for (const [frameIndex, frame] of evictableFrames) {
    if (
      decodedPixels <= IMAGE_RETAINED_DECODED_PIXEL_BUDGET &&
      renderedPixels <= IMAGE_RETAINED_RENDERED_PIXEL_BUDGET
    ) {
      return;
    }
    decodedPixels -= frame.decodedPixels;
    renderedPixels -= frame.renderedPixels;
    disposeProjectedImageFrame(frame);
    cache.frames.delete(frameIndex);
  }
}

type ImageFramePrefetchInput = {
  frameNumbers: readonly number[];
  layout: ImageFrameLayoutModel;
  source: FrameSource;
};

function schedulePrefetchImageFrames(input: ImageFramePrefetchInput) {
  if (input.frameNumbers.length === 0) return;
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(() => prefetchImageFrames(input));
    return;
  }
  window.setTimeout(() => prefetchImageFrames(input), 0);
}

function prefetchImageFrames({
  frameNumbers,
  layout,
  source,
}: ImageFramePrefetchInput) {
  if (frameNumbers.length === 0) return;
  source.prefetch(
    frameNumbers.flatMap((frameNumber) => {
      const frame = getImageFrameLayout(layout, frameNumber);
      return frame ? [frame.frameIndex] : [];
    }),
  );
}

function frameDecodedPixels(source: FrameSource, frameIndex: number) {
  const size = source.frames[frameIndex]?.intrinsicSize;
  return size ? size.width * size.height : 0;
}

function frameRenderedPixels(frame: ImageFrameLayout) {
  const dpr = getImageDevicePixelRatio();
  return (
    Math.max(1, Math.floor(frame.width * dpr)) *
    Math.max(1, Math.floor(frame.height * dpr))
  );
}

function disposeImageFrameProjectionCache(cache: ImageFrameProjectionCache) {
  for (const projectedFrame of cache.frames.values()) {
    disposeProjectedImageFrame(projectedFrame);
  }
  cache.frames.clear();
}

function disposeProjectedImageFrame(projectedFrame: ProjectedImageFrame) {
  if (!projectedFrame.isLive) return;
  projectedFrame.isLive = false;
  deferImageRootUnmount(projectedFrame.root);
  projectedFrame.shell.remove();
}

function deferImageRootUnmount(root: Root) {
  const unmount = () => root.unmount();
  if (typeof queueMicrotask === "function") {
    queueMicrotask(unmount);
    return;
  }
  window.setTimeout(unmount, 0);
}

function getImageProjectionSourceKey(source: FrameSource) {
  const cached = imageProjectionSourceKeys.get(source);
  if (cached) return cached;
  const key = nextImageProjectionSourceKey;
  nextImageProjectionSourceKey += 1;
  imageProjectionSourceKeys.set(source, key);
  return key;
}

function getImageProjectionCallbackKey(
  callback: ImageProjectionCallback | undefined,
) {
  if (!callback) return 0;
  const cached = imageProjectionCallbackKeys.get(callback);
  if (cached) return cached;
  const key = nextImageProjectionCallbackKey;
  nextImageProjectionCallbackKey += 1;
  imageProjectionCallbackKeys.set(callback, key);
  return key;
}

function resizeImageCanvas(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
  { preserve }: { preserve: boolean },
) {
  if (canvas.width === width && canvas.height === height) return null;
  const shouldPreserve =
    preserve && canvas.dataset.imageFrameRendered === "true";
  const previousCanvas =
    shouldPreserve && canvas.width > 0 && canvas.height > 0
      ? copyCanvasContents(canvas)
      : null;
  if (canvas.width !== width) canvas.width = width;
  if (canvas.height !== height) canvas.height = height;
  return previousCanvas;
}

function copyCanvasContents(canvas: HTMLCanvasElement) {
  const copy = document.createElement("canvas");
  copy.width = canvas.width;
  copy.height = canvas.height;
  const context = copy.getContext("2d");
  if (!context) return null;
  try {
    context.drawImage(canvas, 0, 0);
  } catch {
    return null;
  }
  return copy;
}

function preserveCanvasImage(
  context: CanvasRenderingContext2D,
  source: CanvasImageSource,
  width: number,
  height: number,
) {
  try {
    context.drawImage(source, 0, 0, width, height);
  } catch {
    /* Best-effort preservation must not fail the real frame render. */
  }
}

function getImageDevicePixelRatio() {
  const dpr = typeof window === "undefined" ? 1 : window.devicePixelRatio;
  return Number.isFinite(dpr) && dpr > 0 ? dpr : 1;
}

function setImagePixelStyle(
  element: HTMLElement,
  property: "height" | "width",
  value: number,
) {
  setImageStyle(element, property, `${value}px`);
}

function setImageStyle(
  element: HTMLElement,
  property: "height" | "transform" | "width",
  value: string,
) {
  if (element.style.getPropertyValue(property) === value) return;
  element.style.setProperty(property, value);
}

function assignImageRef<T>(ref: React.Ref<T> | undefined, value: T | null) {
  if (!ref) return;
  if (typeof ref === "function") {
    ref(value);
    return;
  }
  ref.current = value;
}

function notifyImageFrameRenderTiming(
  callback: ((timing: ImageFrameRenderTiming) => void) | undefined,
  timing: ImageFrameRenderTiming,
) {
  try {
    callback?.(timing);
  } catch {
    /* Instrumentation callbacks must not affect frame rendering. */
  }
}

function now() {
  return typeof performance === "undefined" ? Date.now() : performance.now();
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import { Skeleton } from "@/components/ui/skeleton";
import { ViewerControlsSkeleton } from "@/components/ui/viewer-controls";

export function ImageViewerFallback({
  className,
  bare = false,
  fallbackFrameSize,
  scale,
  controls = true,
}: {
  className?: string;
  bare?: boolean;
  fallbackFrameSize?: { width: number; height: number };
  scale?: number;
  controls?: boolean;
}) {
  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "bg-muted/20 h-full" : "bg-muted/30 rounded-xl border",
        className,
      )}
      data-slot="image-viewer"
    >
      {controls ? (
        <ViewerControlsSkeleton position zoom rotate download />
      ) : null}
      <div className="min-h-0 flex-1 overflow-auto">
        <div className="flex flex-col items-center p-4">
          <ImageFrameSkeleton frameSize={fallbackFrameSize} scale={scale} />
        </div>
      </div>
    </div>
  );
}

function ImageFrameSkeleton({
  frameSize,
  scale,
}: {
  frameSize?: { width: number; height: number };
  scale?: number;
}) {
  const normalizedScale =
    scale !== undefined && Number.isFinite(scale) && scale > 0
      ? Math.min(5, Math.max(0.25, scale))
      : null;
  const style: React.CSSProperties | undefined = frameSize
    ? normalizedScale !== null
      ? {
          width: frameSize.width * normalizedScale,
          height: frameSize.height * normalizedScale,
        }
      : {
          aspectRatio: `${frameSize.width} / ${frameSize.height}`,
          minWidth: frameSize.width * 0.25,
        }
    : { aspectRatio: "4 / 3" };

  return (
    <Skeleton
      aria-hidden
      className="ring-border w-full rounded-none shadow-sm ring-1"
      data-slot="image-frame-skeleton"
      style={style}
    />
  );
}

export type QuarterTurn = 0 | 90 | 180 | 270;

export interface Size {
  width: number;
  height: number;
}

export interface NormalizedBox {
  left: number;
  top: number;
  width: number;
  height: number;
}

export interface FrameOverlayProps {
  frameNumber: number;
  frameRect: Size;
  scale: number;
  rotation: QuarterTurn;
}

export function normalizeRotation(rotation: number): QuarterTurn {
  const normalized = ((rotation % 360) + 360) % 360;
  if (normalized === 90 || normalized === 180 || normalized === 270) {
    return normalized;
  }
  return 0;
}

export function isRotatedSideways(rotation: QuarterTurn): boolean {
  return rotation === 90 || rotation === 270;
}

export function rotatedSize(size: Size, rotation: QuarterTurn): Size {
  return isRotatedSideways(rotation)
    ? { width: size.height, height: size.width }
    : size;
}

export function frameCssSize(
  intrinsicSize: Size,
  scale: number,
  rotation: QuarterTurn,
): Size {
  const size = rotatedSize(intrinsicSize, rotation);
  return {
    width: size.width * scale,
    height: size.height * scale,
  };
}

export function rotateNormalizedBox(
  box: NormalizedBox,
  rotation: QuarterTurn,
): NormalizedBox {
  if (rotation === 90) {
    return {
      left: 1 - box.top - box.height,
      top: box.left,
      width: box.height,
      height: box.width,
    };
  }
  if (rotation === 180) {
    return {
      left: 1 - box.left - box.width,
      top: 1 - box.top - box.height,
      width: box.width,
      height: box.height,
    };
  }
  if (rotation === 270) {
    return {
      left: box.top,
      top: 1 - box.left - box.width,
      width: box.height,
      height: box.width,
    };
  }
  return box;
}

export function frameNumberToIndex(frameNumber: number): number {
  if (!Number.isFinite(frameNumber)) return 0;
  return Math.max(0, Math.floor(frameNumber) - 1);
}

export function frameIndexToNumber(frameIndex: number): number {
  return frameIndex + 1;
}

import type { Size } from "@/lib/image-geometry";
import {
  isViewerFormatError,
  ViewerFormatError,
  type ViewerFormatErrorMapperOptions,
} from "@/lib/viewer-errors";

export class ImageLoadError extends ViewerFormatError {
  constructor(message: string, options?: ErrorOptions) {
    super({
      format: "image",
      kind: "load_failed",
      message,
      cause: options?.cause,
    });
    this.name = "ImageLoadError";
  }
}

export class ImageDecodeError extends ViewerFormatError {
  constructor(message: string, options?: ErrorOptions) {
    super({
      format: "image",
      kind: "decode_failed",
      message,
      cause: options?.cause,
    });
    this.name = "ImageDecodeError";
  }
}

export class ImageSourceDisposedError extends ViewerFormatError {
  constructor(message = "Image source disposed", options?: ErrorOptions) {
    super({
      format: "image",
      kind: "disposed",
      message,
      cause: options?.cause,
    });
    this.name = "ImageSourceDisposedError";
  }
}

export class ImageFrameIndexError extends ViewerFormatError {
  constructor(frameIndex: number, frameCount: number) {
    super({
      format: "image",
      kind: "index_out_of_range",
      message: `Invalid image frame index ${frameIndex}; expected 0-${Math.max(0, frameCount - 1)}`,
    });
    this.name = "ImageFrameIndexError";
  }
}

export function toImageFormatError(
  error: unknown,
  options: ViewerFormatErrorMapperOptions,
): ViewerFormatError {
  if (isViewerFormatError(error)) return error;
  if (options.kind === "load_failed") {
    return new ImageLoadError(options.message, { cause: error });
  }
  if (options.kind === "decode_failed") {
    return new ImageDecodeError(options.message, { cause: error });
  }
  if (options.kind === "disposed") {
    return new ImageSourceDisposedError(options.message, { cause: error });
  }
  return new ViewerFormatError({
    format: "image",
    kind: options.kind,
    message: options.message,
    cause: error,
  });
}

export interface FrameDescriptor {
  intrinsicSize: Size;
}

export interface FrameSource {
  kind: "native-image" | "tiff";
  frames: readonly FrameDescriptor[];
  acquire(frameIndex: number): Promise<ImageBitmap>;
  hasDecodedFrame(frameIndex: number): boolean;
  prefetch(frameIndexes: readonly number[]): void;
  release(frameIndex: number): void;
  dispose(reason?: Error): void;
}

interface BitmapCacheOptions {
  maxDecodedFrames: number;
  maxDecodedPixels?: number;
}

export class BitmapCache {
  private readonly bitmaps = new Map<number, ImageBitmap>();
  private readonly pinnedFrameCounts = new Map<number, number>();
  private readonly frameRecency: number[] = [];
  private decodedPixels = 0;

  constructor(private readonly options: BitmapCacheOptions) {}

  get(frameIndex: number): ImageBitmap | undefined {
    const bitmap = this.bitmaps.get(frameIndex);
    if (bitmap) this.touch(frameIndex);
    return bitmap;
  }

  set(frameIndex: number, bitmap: ImageBitmap) {
    const previousBitmap = this.bitmaps.get(frameIndex);
    if (previousBitmap && previousBitmap !== bitmap) {
      this.decodedPixels -= imageBitmapPixels(previousBitmap);
      closeBitmap(previousBitmap);
    }
    if (!previousBitmap) {
      this.decodedPixels += imageBitmapPixels(bitmap);
    } else if (previousBitmap !== bitmap) {
      this.decodedPixels += imageBitmapPixels(bitmap);
    }
    this.bitmaps.set(frameIndex, bitmap);
    this.touch(frameIndex);
    this.evict();
  }

  pin(frameIndex: number) {
    this.pinnedFrameCounts.set(
      frameIndex,
      (this.pinnedFrameCounts.get(frameIndex) ?? 0) + 1,
    );
    this.touch(frameIndex);
  }

  unpin(frameIndex: number) {
    const pinCount = this.pinnedFrameCounts.get(frameIndex) ?? 0;
    if (pinCount <= 1) {
      this.pinnedFrameCounts.delete(frameIndex);
    } else {
      this.pinnedFrameCounts.set(frameIndex, pinCount - 1);
    }
    this.evict();
  }

  has(frameIndex: number): boolean {
    return this.bitmaps.has(frameIndex);
  }

  isPinned(frameIndex: number): boolean {
    return (this.pinnedFrameCounts.get(frameIndex) ?? 0) > 0;
  }

  dispose() {
    for (const bitmap of this.bitmaps.values()) closeBitmap(bitmap);
    this.bitmaps.clear();
    this.pinnedFrameCounts.clear();
    this.frameRecency.length = 0;
    this.decodedPixels = 0;
  }

  private touch(frameIndex: number) {
    const position = this.frameRecency.indexOf(frameIndex);
    if (position >= 0) this.frameRecency.splice(position, 1);
    this.frameRecency.push(frameIndex);
  }

  private evict() {
    for (const frameIndex of [...this.frameRecency]) {
      if (
        this.bitmaps.size <= this.options.maxDecodedFrames &&
        this.decodedPixels <= this.maxDecodedPixels
      ) {
        break;
      }
      if (this.isPinned(frameIndex)) continue;
      const bitmap = this.bitmaps.get(frameIndex);
      if (bitmap) {
        this.decodedPixels -= imageBitmapPixels(bitmap);
        closeBitmap(bitmap);
      }
      this.bitmaps.delete(frameIndex);
      this.frameRecency.splice(this.frameRecency.indexOf(frameIndex), 1);
    }
  }

  private get maxDecodedPixels() {
    return this.options.maxDecodedPixels ?? Number.POSITIVE_INFINITY;
  }
}

interface CreateFrameSourceOptions {
  kind: FrameSource["kind"];
  frames: readonly FrameDescriptor[];
  decode(frameIndex: number): Promise<ImageBitmap>;
  cancelDecode?: (frameIndex: number, reason: Error) => void;
  maxDecodedFrames: number;
  maxDecodedPixels?: number;
  initialBitmaps?: readonly InitialBitmap[];
  onDispose?: (reason: Error) => void;
}

interface InitialBitmap {
  frameIndex: number;
  bitmap: ImageBitmap;
}

interface InflightFrameDecode {
  promise: Promise<ImageBitmap>;
  reject(error: Error): void;
  pinCount: number;
}

export function createFrameSource({
  kind,
  frames,
  decode,
  cancelDecode,
  maxDecodedFrames,
  maxDecodedPixels,
  initialBitmaps = [],
  onDispose,
}: CreateFrameSourceOptions): FrameSource {
  try {
    validateFrameDescriptors(frames);
  } catch (error) {
    closeInitialBitmaps(initialBitmaps);
    throw error;
  }
  const bitmapCache = new BitmapCache({ maxDecodedFrames, maxDecodedPixels });
  const inflightDecodes = new Map<number, InflightFrameDecode>();
  let disposed = false;

  for (const { frameIndex, bitmap } of initialBitmaps) {
    if (isValidFrameIndex(frameIndex, frames.length)) {
      bitmapCache.set(frameIndex, bitmap);
    } else {
      closeBitmap(bitmap);
    }
  }

  return {
    kind,
    frames,
    acquire(frameIndex) {
      if (disposed) return Promise.reject(new ImageSourceDisposedError());
      if (!isValidFrameIndex(frameIndex, frames.length)) {
        return Promise.reject(
          new ImageFrameIndexError(frameIndex, frames.length),
        );
      }
      bitmapCache.pin(frameIndex);
      const bitmap = bitmapCache.get(frameIndex);
      if (bitmap) return Promise.resolve(bitmap);

      let inflight = inflightDecodes.get(frameIndex);
      if (!inflight) {
        let rejectInflight: (error: Error) => void = () => {};
        const currentInflight = {
          reject: rejectInflight,
          pinCount: 0,
        } as InflightFrameDecode;
        const promise = new Promise<ImageBitmap>((resolve, reject) => {
          rejectInflight = reject;
          currentInflight.reject = reject;
          let decodedPromise: Promise<ImageBitmap>;
          try {
            decodedPromise = decode(frameIndex);
          } catch (error) {
            decodedPromise = Promise.reject(error);
          }
          decodedPromise
            .then((decodedBitmap) => {
              if (inflightDecodes.get(frameIndex) !== currentInflight) {
                closeBitmap(decodedBitmap);
                reject(
                  new ImageSourceDisposedError("Image frame decode canceled"),
                );
                return;
              }
              inflightDecodes.delete(frameIndex);
              if (disposed) {
                closeBitmap(decodedBitmap);
                reject(new ImageSourceDisposedError());
                return;
              }
              bitmapCache.set(frameIndex, decodedBitmap);
              resolve(decodedBitmap);
            })
            .catch((error) => {
              if (inflightDecodes.get(frameIndex) === currentInflight) {
                inflightDecodes.delete(frameIndex);
                while (currentInflight.pinCount > 0) {
                  currentInflight.pinCount -= 1;
                  bitmapCache.unpin(frameIndex);
                }
              }
              reject(toImageDecodeError(error));
            });
        });
        currentInflight.promise = promise;
        inflight = currentInflight;
        inflightDecodes.set(frameIndex, inflight);
      }
      inflight.pinCount += 1;

      return inflight.promise;
    },
    hasDecodedFrame(frameIndex) {
      if (disposed) return false;
      if (!isValidFrameIndex(frameIndex, frames.length)) return false;
      return bitmapCache.has(frameIndex);
    },
    prefetch(frameIndexes) {
      if (disposed) return;
      for (const frameIndex of frameIndexes) {
        if (!isValidFrameIndex(frameIndex, frames.length)) continue;
        if (bitmapCache.has(frameIndex)) continue;
        if (inflightDecodes.has(frameIndex)) continue;
        void this.acquire(frameIndex)
          .catch(() => undefined)
          .finally(() => this.release(frameIndex));
      }
    },
    release(frameIndex) {
      if (!isValidFrameIndex(frameIndex, frames.length)) return;
      if (disposed) return;
      bitmapCache.unpin(frameIndex);
      const inflight = inflightDecodes.get(frameIndex);
      if (inflight) inflight.pinCount = Math.max(0, inflight.pinCount - 1);
      if (
        inflight &&
        !bitmapCache.isPinned(frameIndex) &&
        !bitmapCache.has(frameIndex)
      ) {
        const reason = new ImageSourceDisposedError(
          "Image frame decode canceled",
        );
        inflight.reject(reason);
        inflightDecodes.delete(frameIndex);
        safeCancelDecode(cancelDecode, frameIndex, reason);
      }
    },
    dispose(reason = new ImageSourceDisposedError()) {
      if (disposed) return;
      disposed = true;
      bitmapCache.dispose();
      for (const [frameIndex, inflight] of inflightDecodes) {
        inflight.reject(reason);
        safeCancelDecode(cancelDecode, frameIndex, reason);
      }
      inflightDecodes.clear();
      onDispose?.(reason);
    },
  };
}

export async function createNativeImageFrameSource(
  bytes: ArrayBuffer,
  contentType: string | null,
  maxDecodedFrames: number,
  maxDecodedPixels?: number,
): Promise<FrameSource> {
  const blob = new Blob([bytes], { type: contentType ?? "" });
  return createNativeImageFrameSourceFromBlob(
    blob,
    maxDecodedFrames,
    maxDecodedPixels,
  );
}

export async function createNativeImageFrameSourceFromBlob(
  blob: Blob,
  maxDecodedFrames: number,
  maxDecodedPixels?: number,
): Promise<FrameSource> {
  let probe: ImageBitmap;
  try {
    probe = await createImageBitmap(blob);
  } catch (error) {
    throw toImageFormatError(error, {
      kind: "decode_failed",
      message: "Failed to decode image",
    });
  }
  const frames: FrameDescriptor[] = [
    { intrinsicSize: { width: probe.width, height: probe.height } },
  ];
  return createFrameSource({
    kind: "native-image",
    frames,
    maxDecodedFrames,
    maxDecodedPixels,
    initialBitmaps: [{ frameIndex: 0, bitmap: probe }],
    decode: () => createImageBitmap(blob),
  });
}

export function isDeclaredTiff(
  src: string,
  contentType: string | null,
): boolean {
  return /\.tiff?($|[?#])/i.test(src) || isTiffContentType(contentType);
}

export function isDeclaredNativeImage(
  src: string,
  contentType: string | null,
): boolean {
  if (isDeclaredTiff(src, contentType)) return false;
  if (!contentType)
    return /\.(png|jpe?g|webp|gif|avif|bmp|ico)($|[?#])/i.test(src);
  return /^image\/(png|jpe?g|webp|gif|avif|bmp|x-icon|vnd\.microsoft\.icon)(;|$)/i.test(
    contentType,
  );
}

export function isTiffBytes(
  src: string,
  contentType: string | null,
  bytes: ArrayBuffer,
): boolean {
  if (isDeclaredTiff(src, contentType)) return true;
  const b = new Uint8Array(bytes, 0, Math.min(4, bytes.byteLength));
  return (
    (b[0] === 0x49 && b[1] === 0x49 && b[2] === 0x2a && b[3] === 0x00) ||
    (b[0] === 0x4d && b[1] === 0x4d && b[2] === 0x00 && b[3] === 0x2a)
  );
}

export function closeBitmap(bitmap: ImageBitmap | undefined) {
  try {
    bitmap?.close();
  } catch {
    // Disposal must stay idempotent across browser edges and test doubles.
  }
}

function imageBitmapPixels(bitmap: ImageBitmap) {
  const pixels = bitmap.width * bitmap.height;
  return Number.isFinite(pixels) && pixels > 0 ? pixels : 0;
}

function toImageDecodeError(error: unknown): ViewerFormatError {
  if (error instanceof ImageSourceDisposedError) return error;
  return error instanceof ImageDecodeError
    ? error
    : toImageFormatError(error, {
        kind: "decode_failed",
        message: "Image decode failed",
      });
}

function safeCancelDecode(
  cancelDecode: CreateFrameSourceOptions["cancelDecode"] | undefined,
  frameIndex: number,
  reason: Error,
) {
  try {
    cancelDecode?.(frameIndex, reason);
  } catch {
    // Local lifecycle cleanup has already happened; cancellation transport is best-effort.
  }
}

function isValidFrameIndex(frameIndex: number, frameCount: number) {
  return (
    Number.isInteger(frameIndex) && frameIndex >= 0 && frameIndex < frameCount
  );
}

function isTiffContentType(contentType: string | null): boolean {
  return contentType ? /^image\/(x-)?tiff?(;|$)/i.test(contentType) : false;
}

function validateFrameDescriptors(frames: readonly FrameDescriptor[]) {
  if (frames.length === 0) {
    throw new ImageDecodeError("Image does not contain any frames");
  }
  for (const [frameIndex, frame] of frames.entries()) {
    const { width, height } = frame.intrinsicSize;
    if (
      !Number.isFinite(width) ||
      !Number.isFinite(height) ||
      width <= 0 ||
      height <= 0
    ) {
      throw new ImageDecodeError(
        `Image frame ${frameIndex + 1} has invalid dimensions`,
      );
    }
  }
}

function closeInitialBitmaps(initialBitmaps: readonly InitialBitmap[]) {
  for (const { bitmap } of initialBitmaps) closeBitmap(bitmap);
}

import {
  createNativeImageFrameSourceFromBlob,
  ImageDecodeError,
  ImageLoadError,
  ImageSourceDisposedError,
  isDeclaredNativeImage,
  isDeclaredTiff,
  isTiffBytes,
  type FrameSource,
} from "@/lib/image-frame-source";
import {
  createTiffFrameSource,
  type TiffWorkerFactory,
} from "@/lib/image-tiff-source";
import type {
  ViewerContentBlob,
  ViewerContentBytes,
  ViewerContentDirectUrl,
  ViewerContentIdentity,
  ViewerContentMime,
  ViewerContentPayload,
} from "@/lib/viewer-resource";

const DEFAULT_MAX_DECODED_FRAMES = 16;
const DEFAULT_MAX_DECODED_PIXELS = 64_000_000;
const DEFAULT_UNCLAIMED_SOURCE_TIMEOUT_MS = 30_000;
const DEFAULT_RELEASED_SOURCE_TIMEOUT_MS = 10_000;
const TIFF_SIGNATURE_BYTE_COUNT = 4;

export interface FrameSourceLease {
  source: FrameSource;
  release(): void;
}

export type ImageSourceContent = ViewerContentIdentity &
  ViewerContentDirectUrl &
  ViewerContentMime &
  ViewerContentPayload &
  ViewerContentBlob &
  ViewerContentBytes;

type FrameSourceEntryState = "pending" | "resolved" | "evictable" | "disposed";

interface FrameSourceEntry {
  content: ImageSourceContent;
  abortController: AbortController;
  promise: Promise<FrameSource>;
  source?: FrameSource;
  leaseCount: number;
  state: FrameSourceEntryState;
  disposeReason?: Error;
  disposeTimer?: ReturnType<typeof setTimeout>;
}

interface FrameSourceManagerOptions {
  maxDecodedFrames?: number;
  maxDecodedPixels?: number;
  releasedSourceTimeoutMs?: number;
  unclaimedSourceTimeoutMs?: number;
}

export class FrameSourceManager {
  private readonly entries = new Map<string, FrameSourceEntry>();
  private readonly maxDecodedFrames: number;
  private readonly maxDecodedPixels: number;
  private readonly releasedSourceTimeoutMs: number;
  private readonly unclaimedSourceTimeoutMs: number;

  constructor(options: FrameSourceManagerOptions = {}) {
    this.maxDecodedFrames =
      options.maxDecodedFrames ?? DEFAULT_MAX_DECODED_FRAMES;
    this.maxDecodedPixels =
      options.maxDecodedPixels ?? DEFAULT_MAX_DECODED_PIXELS;
    this.releasedSourceTimeoutMs =
      options.releasedSourceTimeoutMs ?? DEFAULT_RELEASED_SOURCE_TIMEOUT_MS;
    this.unclaimedSourceTimeoutMs =
      options.unclaimedSourceTimeoutMs ?? DEFAULT_UNCLAIMED_SOURCE_TIMEOUT_MS;
  }

  load(
    content: ImageSourceContent,
    createTiffWorker: TiffWorkerFactory,
  ): Promise<FrameSource> {
    const loadKey = content.key;
    let entry = this.entries.get(loadKey);
    if (!entry) {
      const abortController = new AbortController();
      const newEntry: FrameSourceEntry = {
        content,
        abortController,
        promise: Promise.resolve().then(() =>
          this.createSource(content, createTiffWorker, abortController.signal),
        ),
        leaseCount: 0,
        state: "pending",
      };
      newEntry.promise = newEntry.promise
        .then((source) => {
          newEntry.source = source;
          if (newEntry.state === "disposed") {
            source.dispose(
              newEntry.disposeReason ?? new ImageSourceDisposedError(),
            );
            this.entries.delete(loadKey);
            newEntry.state = "disposed";
            throw new ImageLoadError("Image source was disposed before use");
          }
          if (newEntry.leaseCount === 0) {
            newEntry.state = "evictable";
            this.scheduleDispose(
              newEntry,
              this.unclaimedSourceTimeoutMs,
              new ImageSourceDisposedError(),
            );
          } else {
            newEntry.state = "resolved";
          }
          return source;
        })
        .catch((error) => {
          if (this.entries.get(loadKey) === newEntry) {
            this.entries.delete(loadKey);
          }
          if (
            newEntry.state === "disposed" &&
            error instanceof ImageDecodeError
          ) {
            throw newEntry.disposeReason ?? new ImageSourceDisposedError();
          }
          throw error;
        });
      entry = newEntry;
      this.entries.set(loadKey, entry);
    }
    return entry.promise;
  }

  retain(
    content: ViewerContentIdentity,
    source: FrameSource,
  ): FrameSourceLease | null {
    const entry = this.entries.get(content.key);
    if (!entry || entry.source !== source || entry.state === "disposed") {
      return null;
    }
    this.cancelDispose(entry);
    entry.state = "resolved";
    entry.leaseCount += 1;
    let hasReleased = false;
    return {
      source,
      release: () => {
        if (hasReleased) return;
        hasReleased = true;
        const current = this.entries.get(content.key);
        if (!current || current.source !== source) return;
        current.leaseCount = Math.max(0, current.leaseCount - 1);
        if (current.leaseCount === 0) {
          current.state = "evictable";
          this.scheduleDispose(
            current,
            this.releasedSourceTimeoutMs,
            new ImageSourceDisposedError(),
          );
        }
      },
    };
  }

  clear() {
    for (const entry of [...this.entries.values()]) {
      this.disposeEntry(entry, new ImageSourceDisposedError());
    }
  }

  private async createSource(
    content: ImageSourceContent,
    createTiffWorker: TiffWorkerFactory,
    signal: AbortSignal,
  ): Promise<FrameSource> {
    const sourceName = imageSourceName(content);
    const declaredContentType = imageContentType(content);

    if (isDeclaredTiff(sourceName, declaredContentType)) {
      return createTiffFrameSource(
        await readContentBytes(content, { signal }),
        createTiffWorker,
        this.maxDecodedFrames,
        signal,
        this.maxDecodedPixels,
      );
    }

    if (isDeclaredNativeImage(sourceName, declaredContentType)) {
      return createNativeImageFrameSourceFromBlob(
        await content.readBlob({ signal }),
        this.maxDecodedFrames,
        this.maxDecodedPixels,
      );
    }

    const blob = await content.readBlob({ signal });
    return this.createSourceFromUnknownBlob(
      sourceName,
      blob,
      createTiffWorker,
      signal,
    );
  }

  private disposeEntry(entry: FrameSourceEntry, reason: Error) {
    if (entry.state === "disposed") return;
    entry.state = "disposed";
    entry.disposeReason = reason;
    this.cancelDispose(entry);
    entry.abortController.abort(reason);
    entry.source?.dispose(reason);
    if (this.entries.get(entry.content.key) === entry) {
      this.entries.delete(entry.content.key);
    }
  }

  private scheduleDispose(
    entry: FrameSourceEntry,
    delayMs: number,
    reason: Error,
  ) {
    this.cancelDispose(entry);
    entry.disposeReason = reason;
    entry.disposeTimer = setTimeout(() => {
      const current = this.entries.get(entry.content.key);
      if (!current || current !== entry || current.leaseCount > 0) return;
      this.disposeEntry(current, reason);
    }, delayMs);
  }

  private cancelDispose(entry: FrameSourceEntry) {
    if (!entry.disposeTimer) return;
    clearTimeout(entry.disposeTimer);
    entry.disposeTimer = undefined;
  }

  private async createSourceFromUnknownBlob(
    sourceName: string,
    blob: Blob,
    createTiffWorker: TiffWorkerFactory,
    signal: AbortSignal,
  ): Promise<FrameSource> {
    const contentType = blob.type || null;
    const prefix = await blob.slice(0, TIFF_SIGNATURE_BYTE_COUNT).arrayBuffer();
    if (isTiffBytes(sourceName, contentType, prefix)) {
      return createTiffFrameSource(
        await blob.arrayBuffer(),
        createTiffWorker,
        this.maxDecodedFrames,
        signal,
        this.maxDecodedPixels,
      );
    }

    return createNativeImageFrameSourceFromBlob(
      blob,
      this.maxDecodedFrames,
      this.maxDecodedPixels,
    );
  }
}

export const imageFrameSourceManager = new FrameSourceManager();

function imageSourceName(content: ViewerContentDirectUrl): string {
  return content.directUrl ?? "";
}

function imageContentType(
  content: ViewerContentPayload & ViewerContentMime,
): string | null {
  if (content.mimeType) return content.mimeType;
  if (content.payload.kind === "blob") return content.payload.blob.type || null;
  return null;
}

function readContentBytes(
  content: ViewerContentBytes,
  options: { signal: AbortSignal },
): Promise<ArrayBuffer> {
  return content.readBytes(options);
}

import {
  closeBitmap,
  createFrameSource,
  ImageDecodeError,
  ImageSourceDisposedError,
  type FrameDescriptor,
  type FrameSource,
} from "@/lib/image-frame-source";
import { ViewerFormatError } from "@/lib/viewer-errors";

export class TiffWorkerError extends ViewerFormatError {
  constructor(message: string, options?: ErrorOptions) {
    super({
      format: "image",
      kind: "worker_failed",
      message,
      cause: options?.cause,
    });
    this.name = "TiffWorkerError";
  }
}

export type TiffWorkerRequest =
  | { type: "init"; buffer: ArrayBuffer }
  | { type: "decodeFrame"; requestId: number; frameIndex: number }
  | { type: "cancelDecode"; requestId: number };

export type TiffWorkerResponse =
  | { type: "initOk"; frames: FrameDescriptor[] }
  | { type: "initError"; message: string }
  | { type: "decodeFrameOk"; requestId: number; bitmap: ImageBitmap }
  | { type: "decodeFrameError"; requestId: number; message: string };

export type TiffWorkerFactory = () => Worker;

interface PendingDecode {
  frameIndex: number;
  resolve(bitmap: ImageBitmap): void;
  reject(error: Error): void;
}

export class TiffWorkerClient {
  private readonly worker: Worker;
  private readonly pendingDecodes = new Map<number, PendingDecode>();
  private initResolve: ((frames: readonly FrameDescriptor[]) => void) | null =
    null;
  private initReject: ((error: Error) => void) | null = null;
  private initAbortCleanup: (() => void) | null = null;
  private nextRequestId = 0;
  private initialized = false;
  private disposed = false;

  constructor(createWorker: TiffWorkerFactory) {
    this.worker = createWorker();
    this.worker.onmessage = (event: MessageEvent<TiffWorkerResponse>) => {
      this.handleMessage(event.data);
    };
    this.worker.onerror = (event) => {
      this.fail(new TiffWorkerError(event.message || "TIFF worker failed"));
    };
    this.worker.onmessageerror = () => {
      this.fail(new TiffWorkerError("TIFF worker sent an unreadable message"));
    };
  }

  init(
    buffer: ArrayBuffer,
    signal?: AbortSignal,
  ): Promise<readonly FrameDescriptor[]> {
    if (this.disposed) {
      return Promise.reject(new TiffWorkerError("TIFF worker disposed"));
    }
    if (this.initResolve) {
      return Promise.reject(
        new TiffWorkerError("TIFF worker already initializing"),
      );
    }
    if (this.initialized) {
      return Promise.reject(
        new TiffWorkerError("TIFF worker already initialized"),
      );
    }
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        this.initAbortCleanup?.();
        this.initAbortCleanup = null;
      };
      this.initResolve = (frames) => {
        cleanup();
        resolve(frames);
      };
      this.initReject = (error) => {
        cleanup();
        reject(error);
      };
      if (signal) {
        const abort = () => {
          this.dispose(abortSignalReason(signal));
        };
        if (signal.aborted) {
          abort();
          return;
        }
        signal.addEventListener("abort", abort, { once: true });
        this.initAbortCleanup = () => {
          signal.removeEventListener("abort", abort);
        };
      }
      try {
        this.worker.postMessage({ type: "init", buffer }, [buffer]);
      } catch (error) {
        const workerError = new TiffWorkerError(
          "Failed to initialize TIFF worker",
          {
            cause: error,
          },
        );
        this.disposed = true;
        this.rejectInit(workerError);
        this.rejectPending(workerError);
        this.worker.terminate();
      }
    });
  }

  decode(frameIndex: number): Promise<ImageBitmap> {
    if (this.disposed) {
      return Promise.reject(new TiffWorkerError("TIFF worker disposed"));
    }
    return new Promise((resolve, reject) => {
      const requestId = this.nextRequestId++;
      this.pendingDecodes.set(requestId, { frameIndex, resolve, reject });
      try {
        this.worker.postMessage({ type: "decodeFrame", requestId, frameIndex });
      } catch (error) {
        const workerError = new TiffWorkerError(
          "Failed to request TIFF frame decode",
          {
            cause: error,
          },
        );
        this.pendingDecodes.delete(requestId);
        this.disposed = true;
        this.rejectPending(workerError);
        this.worker.terminate();
        reject(workerError);
      }
    });
  }

  cancelDecode(
    frameIndex: number,
    reason: Error = new TiffWorkerError("TIFF decode canceled"),
  ) {
    for (const [requestId, pending] of this.pendingDecodes) {
      if (pending.frameIndex !== frameIndex) continue;
      this.pendingDecodes.delete(requestId);
      pending.reject(reason);
      try {
        this.worker.postMessage({ type: "cancelDecode", requestId });
      } catch {
        // The local promise is already rejected; worker transport may be gone.
      }
    }
  }

  dispose(reason: Error = new TiffWorkerError("TIFF worker disposed")) {
    if (this.disposed) return;
    this.disposed = true;
    this.rejectInit(reason);
    this.rejectPending(reason);
    this.worker.terminate();
  }

  private handleMessage(message: TiffWorkerResponse) {
    if (message.type === "initOk") {
      if (!isFrameDescriptorList(message.frames)) {
        this.fail(
          new TiffWorkerError("TIFF worker sent an invalid init response"),
        );
        return;
      }
      try {
        validateWorkerFrameDescriptors(message.frames);
      } catch (error) {
        this.fail(
          error instanceof Error
            ? error
            : new ImageDecodeError("Image decode failed"),
        );
        return;
      }
      this.initialized = true;
      this.initResolve?.(message.frames);
      this.initResolve = null;
      this.initReject = null;
      return;
    }
    if (message.type === "initError") {
      if (typeof message.message !== "string") {
        this.fail(
          new TiffWorkerError("TIFF worker sent an invalid init response"),
        );
        return;
      }
      const error = new TiffWorkerError(message.message);
      this.disposed = true;
      this.rejectPending(error);
      this.rejectInit(error);
      this.worker.terminate();
      return;
    }
    if (message.type === "decodeFrameOk") {
      if (
        !isWorkerRequestId(message.requestId) ||
        !isImageBitmap(message.bitmap)
      ) {
        closeBitmapLike(message.bitmap);
        this.fail(
          new TiffWorkerError("TIFF worker sent an invalid decode response"),
        );
        return;
      }
      const pending = this.pendingDecodes.get(message.requestId);
      this.pendingDecodes.delete(message.requestId);
      if (pending) pending.resolve(message.bitmap);
      else closeBitmap(message.bitmap);
      return;
    }
    if (message.type === "decodeFrameError") {
      if (
        !isWorkerRequestId(message.requestId) ||
        typeof message.message !== "string"
      ) {
        this.fail(
          new TiffWorkerError("TIFF worker sent an invalid decode response"),
        );
        return;
      }
      const pending = this.pendingDecodes.get(message.requestId);
      this.pendingDecodes.delete(message.requestId);
      pending?.reject(new ImageDecodeError(message.message));
      return;
    }
    this.fail(new TiffWorkerError("TIFF worker sent an unknown message"));
  }

  private fail(error: Error) {
    if (this.disposed) return;
    this.disposed = true;
    this.rejectPending(error);
    this.rejectInit(error);
    this.worker.terminate();
  }

  private rejectInit(error: Error) {
    this.initReject?.(error);
    this.initResolve = null;
    this.initReject = null;
  }

  private rejectPending(error: Error) {
    for (const pending of this.pendingDecodes.values()) pending.reject(error);
    this.pendingDecodes.clear();
  }
}

export async function createTiffFrameSource(
  buffer: ArrayBuffer,
  createWorker: TiffWorkerFactory,
  maxDecodedFrames: number,
  signal?: AbortSignal,
  maxDecodedPixels?: number,
): Promise<FrameSource> {
  const client = new TiffWorkerClient(createWorker);
  const frames = await client.init(buffer, signal);
  try {
    return createFrameSource({
      kind: "tiff",
      frames,
      maxDecodedFrames,
      maxDecodedPixels,
      decode: (frameIndex) => client.decode(frameIndex),
      cancelDecode: (frameIndex, reason) =>
        client.cancelDecode(frameIndex, reason),
      onDispose: (reason) => client.dispose(reason),
    });
  } catch (error) {
    client.dispose(error instanceof Error ? error : undefined);
    throw error;
  }
}

function abortSignalReason(signal: AbortSignal): Error {
  return signal.reason instanceof Error
    ? signal.reason
    : new ImageSourceDisposedError();
}

function isWorkerRequestId(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

function isImageBitmap(value: unknown): value is ImageBitmap {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Partial<ImageBitmap>).close === "function" &&
    Number.isFinite((value as Partial<ImageBitmap>).width) &&
    Number.isFinite((value as Partial<ImageBitmap>).height) &&
    (value as Partial<ImageBitmap>).width! > 0 &&
    (value as Partial<ImageBitmap>).height! > 0
  );
}

function closeBitmapLike(value: unknown) {
  if (
    typeof value === "object" &&
    value !== null &&
    typeof (value as Partial<ImageBitmap>).close === "function"
  ) {
    closeBitmap(value as ImageBitmap);
  }
}

function isFrameDescriptorList(value: unknown): value is FrameDescriptor[] {
  return (
    Array.isArray(value) &&
    value.every((frame) => {
      if (typeof frame !== "object" || frame === null) return false;
      const intrinsicSize = (frame as Partial<FrameDescriptor>).intrinsicSize;
      return (
        typeof intrinsicSize === "object" &&
        intrinsicSize !== null &&
        typeof intrinsicSize.width === "number" &&
        typeof intrinsicSize.height === "number"
      );
    })
  );
}

function validateWorkerFrameDescriptors(frames: readonly FrameDescriptor[]) {
  if (frames.length === 0) {
    throw new ImageDecodeError("Image does not contain any frames");
  }
  for (const [frameIndex, frame] of frames.entries()) {
    const { width, height } = frame.intrinsicSize;
    if (
      !Number.isFinite(width) ||
      !Number.isFinite(height) ||
      width <= 0 ||
      height <= 0
    ) {
      throw new ImageDecodeError(
        `Image frame ${frameIndex + 1} has invalid dimensions`,
      );
    }
  }
}

// Web Worker that owns TIFF decode (UTIF) so it never blocks the UI thread.
// The main thread transfers file bytes in once; the worker parses frame metadata
// up front, decodes requested frames on demand, and transfers ImageBitmaps back.
import UTIF from "utif";

import type {
  TiffWorkerRequest,
  TiffWorkerResponse,
} from "@/lib/image-tiff-source";

interface Ifd {
  t256?: number[];
  t257?: number[];
  width?: number;
  height?: number;
  data?: unknown;
}

interface Utif {
  decode(buf: ArrayBuffer): Ifd[];
  decodeImage(buf: ArrayBuffer, ifd: Ifd): void;
  toRGBA8(ifd: Ifd): Uint8Array;
}

const utif = UTIF as Utif;
const ctx = self as unknown as Worker;

let buffer: ArrayBuffer | null = null;
let ifds: Ifd[] = [];
const canceledDecodeRequestIds = new Set<number>();
const decodeQueue: { requestId: number; frameIndex: number }[] = [];
let isDecoding = false;

ctx.onmessage = async (event: MessageEvent<TiffWorkerRequest>) => {
  const message = event.data;

  if (message.type === "init") {
    initialize(message.buffer);
    return;
  }

  if (message.type === "cancelDecode") {
    canceledDecodeRequestIds.add(message.requestId);
    return;
  }

  decodeQueue.push({
    requestId: message.requestId,
    frameIndex: message.frameIndex,
  });
  scheduleDecodeQueue();
};

function scheduleDecodeQueue() {
  if (isDecoding) return;
  setTimeout(processDecodeQueue, 0);
}

async function processDecodeQueue() {
  if (isDecoding) return;
  const next = decodeQueue.shift();
  if (!next) return;
  if (canceledDecodeRequestIds.delete(next.requestId)) {
    scheduleDecodeQueue();
    return;
  }
  isDecoding = true;
  try {
    await decodeFrame(next.requestId, next.frameIndex);
  } finally {
    isDecoding = false;
    if (decodeQueue.length > 0) scheduleDecodeQueue();
  }
}

function initialize(nextBuffer: ArrayBuffer) {
  try {
    buffer = nextBuffer;
    ifds = utif.decode(buffer);
    if (ifds.length === 0) throw new Error("TIFF has no frames");
    post({
      type: "initOk",
      frames: ifds.map((ifd, frameIndex) => {
        const width = frameWidth(ifd);
        const height = frameHeight(ifd);
        if (!width || !height) {
          throw new Error(`TIFF frame ${frameIndex + 1} has no dimensions`);
        }
        return { intrinsicSize: { width, height } };
      }),
    });
  } catch (error) {
    post({ type: "initError", message: errorMessage(error) });
  }
}

async function decodeFrame(requestId: number, frameIndex: number) {
  let didDecode = false;
  let ifd: Ifd | undefined;
  try {
    if (!buffer) throw new Error("worker not initialized");
    if (canceledDecodeRequestIds.delete(requestId)) return;
    if (frameIndex < 0 || frameIndex >= ifds.length) {
      throw new Error(`TIFF frame ${frameIndex + 1} is out of range`);
    }
    ifd = ifds[frameIndex];
    const width = frameWidth(ifd);
    const height = frameHeight(ifd);
    if (!width || !height) {
      throw new Error(`TIFF frame ${frameIndex + 1} has no dimensions`);
    }

    utif.decodeImage(buffer, ifd);
    didDecode = true;
    const rgba = utif.toRGBA8(ifd);
    const image = new ImageData(new Uint8ClampedArray(rgba), width, height);
    const bitmap = await createImageBitmap(image);
    if (canceledDecodeRequestIds.delete(requestId)) {
      bitmap.close();
      return;
    }
    post({ type: "decodeFrameOk", requestId, bitmap }, [bitmap]);
  } catch (error) {
    post({
      type: "decodeFrameError",
      requestId,
      message: `TIFF frame ${frameIndex + 1}: ${errorMessage(error)}`,
    });
  } finally {
    canceledDecodeRequestIds.delete(requestId);
    if (didDecode && ifd) delete ifd.data;
  }
}

function post(message: TiffWorkerResponse, transfer?: Transferable[]): void {
  ctx.postMessage(message, transfer ?? []);
}

function frameWidth(ifd: Ifd): number {
  return ifd.width ?? ifd.t256?.[0] ?? 0;
}

function frameHeight(ifd: Ifd): number {
  return ifd.height ?? ifd.t257?.[0] ?? 0;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "TIFF decode failed";
}

"use client";

import * as React from "react";

const emptySubscribe = () => () => {};
const getClientSnapshot = () => true;
const getServerSnapshot = () => false;

/**
 * SSR gate: `false` on the server (and during hydration's first pass),
 * `true` on the client.
 *
 * This must stay a synchronous external-store read, NOT the
 * `useState(false)` + mount-effect flip. The flip pattern makes every
 * viewer mount its Suspense boundary in a later update; when two such
 * boundaries suspend on pending resources in the same flush as other
 * commit-phase updates (viewer sidebar/geometry registration), React 19's
 * retry lanes desynchronize and re-attempt each other's boundary on every
 * commit — an unbounded synchronous suspend/retry loop that starves the
 * event loop (jsdom tests OOM; browsers busy-spin until the resource
 * resolves). With the store read, client renders suspend on mount, which
 * never enters that loop. Regression-guarded in
 * tests/pdf-viewer-thumbnails.test.tsx ("shares one document resource…").
 */
export function useIsClient(): boolean {
  return React.useSyncExternalStore(
    emptySubscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
}

"use client";

import * as React from "react";
import { RotateCcw } from "lucide-react";

import { cn } from "@/lib/utils";
import type { ViewerDownloadAction } from "@/lib/viewer-download-actions";
import {
  toViewerErrorInfo,
  type ViewerErrorContext,
  type ViewerFormat,
} from "@/lib/viewer-errors";

import { Button } from "./button";
import { ViewerDownloadButton } from "./viewer-download";

export interface ViewerErrorStateProps extends ViewerErrorContext {
  error: unknown;
  download?: ViewerDownloadAction | null;
  className?: string;
  bare?: boolean;
  variant?: "card" | "document" | "inline";
  onRetry?: () => void;
}

export function ViewerErrorState({
  error,
  format,
  sourceKind,
  canDownload,
  retry,
  download,
  className,
  bare = false,
  variant = "card",
  onRetry,
}: ViewerErrorStateProps) {
  const info = toViewerErrorInfo(error, {
    format,
    sourceKind,
    canDownload: canDownload ?? Boolean(download && !download.isDisabled),
    retry,
  });
  const showRetry = info.isRetryable && onRetry;
  const showDownload =
    info.isDownloadUseful && download != null && !download.isDisabled;

  return (
    <div
      className={cn(errorStateClassName({ bare, variant }), className)}
      data-error-domain={info.domain}
      data-error-format={info.format}
      data-error-kind={info.kind}
      data-error-message={info.message}
      data-slot="viewer-error"
      role="alert"
    >
      <p>{info.userMessage}</p>
      {showRetry || showDownload ? (
        <div className="flex items-center gap-2">
          {showRetry ? (
            <Button variant="outline" size="sm" onClick={onRetry}>
              <RotateCcw className="mr-1.5 size-4" />
              Retry
            </Button>
          ) : null}
          {showDownload ? (
            <ViewerDownloadButton
              action={download}
              variant={showRetry ? "ghost" : "outline"}
              size="sm"
              className=""
              showLabel
            />
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

export interface ViewerErrorBoundaryProps extends ViewerErrorContext {
  children: React.ReactNode;
  resetKey?: unknown;
  download?: ViewerDownloadAction | null;
  className?: string;
  bare?: boolean;
  variant?: "card" | "document" | "inline";
  mapError?: (error: unknown) => unknown;
  onRetry?: (error: unknown) => void;
  onCaughtError?: (error: unknown, errorInfo: React.ErrorInfo) => void;
}

export class ViewerErrorBoundary extends React.Component<
  ViewerErrorBoundaryProps,
  { error: unknown | null; retryKey: number }
> {
  state: Readonly<{ error: unknown | null; retryKey: number }> = {
    error: null,
    retryKey: 0,
  };

  componentDidUpdate(previousProps: ViewerErrorBoundaryProps) {
    if (
      previousProps.resetKey !== this.props.resetKey &&
      this.state.error != null
    ) {
      this.setState({ error: null });
    }
  }

  static getDerivedStateFromError(error: unknown) {
    return { error };
  }

  componentDidCatch(error: unknown, errorInfo: React.ErrorInfo) {
    this.props.onCaughtError?.(error, errorInfo);
  }

  render() {
    if (this.state.error != null) {
      const error = this.props.mapError
        ? this.props.mapError(this.state.error)
        : this.state.error;

      return (
        <ViewerErrorState
          error={error}
          format={this.props.format}
          sourceKind={this.props.sourceKind}
          canDownload={this.props.canDownload}
          retry={this.props.retry}
          download={this.props.download}
          className={this.props.className}
          bare={this.props.bare}
          variant={this.props.variant}
          onRetry={() => {
            this.setState((state) => ({
              error: null,
              retryKey: state.retryKey + 1,
            }));
            this.props.onRetry?.(this.state.error);
          }}
        />
      );
    }

    return (
      <React.Fragment key={this.state.retryKey}>
        {this.props.children}
      </React.Fragment>
    );
  }
}

function errorStateClassName({
  bare,
  variant,
}: {
  bare: boolean;
  variant: "card" | "document" | "inline";
}) {
  if (variant === "inline") {
    return "flex h-24 flex-col items-center justify-center gap-3 px-3 text-center text-xs text-muted-foreground";
  }
  return cn(
    "flex min-h-64 flex-col items-center justify-center gap-3 p-6 text-center text-sm text-muted-foreground",
    bare ? "bg-muted/20" : "rounded-xl border bg-muted/30",
    variant === "document" && "min-h-full",
  );
}

export type { ViewerFormat };

// Ambient shim for the `utif` package, which ships no type declarations
// (and has no @types/utif on npm). shadcn's registry build strips leading
// comments from source files, so an inline `@ts-expect-error` above the import
// does not survive into the published item — a real declaration is required for
// a fresh consumer install to typecheck. The decode workers cast the default
// export to their own local shapes, so an opaque `any` default is sufficient.
declare module "utif" {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const UTIF: any;
  export default UTIF;
}

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

import type {
  ViewerDocumentLayoutModel,
  ViewerDocumentPhysicalScrollPosition,
  ViewerDocumentResolvedScrollTarget,
  ViewerDocumentScrollMapper,
  ViewerDocumentScrollMetrics,
  ViewerDocumentScrollTargetResolver,
} from "./viewer-types";
import { useViewerDocumentGeometryTransaction } from "./viewer-document-geometry";

const VIEWER_DOCUMENT_SCROLL_IDLE_MS = 120;
const VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON = 1;
const VIEWER_DOCUMENT_SCROLL_RESTORE_MAX_FRAMES = 45;
const VIEWER_DOCUMENT_INTERNAL_SCROLL_SUPPRESS_MS = 120;

type ViewerDocumentScrollIntent<Target> =
  | {
      kind: "idle";
    }
  | {
      kind: "user";
    }
  | {
      behavior: ScrollBehavior;
      kind: "programmatic";
      sequence: number;
      target: Target;
      targetLeft?: number;
      targetTop: number;
    };

type PendingViewerDocumentScrollRestore = {
  attempts: number;
  options: ScrollToOptions;
  targetTop: number;
};

type ViewerDocumentScrollEventResult = {
  source: "internal" | "programmatic" | "user";
};

export function useViewerDocumentScroll<Anchor, Target>({
  copyScrollTarget,
  layout,
  resetKey,
  resolveScrollTarget,
  scrollMapper,
}: {
  copyScrollTarget?: (target: Target) => Target;
  layout: ViewerDocumentLayoutModel<Anchor>;
  resetKey?: unknown;
  resolveScrollTarget?: ViewerDocumentScrollTargetResolver<Anchor, Target>;
  scrollMapper: ViewerDocumentScrollMapper;
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null);
  const scrollPageOffsetRef = React.useRef(0);
  const pendingScrollRestoreRef =
    React.useRef<PendingViewerDocumentScrollRestore | null>(null);
  const pendingScrollRestoreFrameRef = React.useRef(0);
  const flushPendingScrollRestoreRef = React.useRef<() => void>(() => {});
  const isInternalScrollWriteRef = React.useRef(false);
  const internalScrollWriteTimeoutRef = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null);
  const viewportResetKeyRef = React.useRef<unknown>(resetKey);
  const didMountResetEffectRef = React.useRef(false);
  const committedLayoutRef = React.useRef(layout);
  const committedResetKeyRef = React.useRef<unknown>(resetKey);
  const geometryTransaction = useViewerDocumentGeometryTransaction({
    layout,
    resetKey,
  });
  const {
    cacheAnchor,
    cacheReadingAnchor,
    cacheVisualLayerRect,
    cancel: cancelGeometryTransaction,
    classifyLayoutChange,
    commit,
    prepare,
    recordStableState,
    reset: resetGeometryTransaction,
  } = geometryTransaction;
  const scrollIntent = useViewerDocumentScrollIntentController<Target>();
  const [viewportElement, setViewportElementState] =
    React.useState<HTMLDivElement | null>(null);

  const cancelPendingScrollRestore = React.useCallback(() => {
    pendingScrollRestoreRef.current = null;
    if (pendingScrollRestoreFrameRef.current === 0) return;
    cancelAnimationFrame(pendingScrollRestoreFrameRef.current);
    pendingScrollRestoreFrameRef.current = 0;
  }, []);

  const clearInternalScrollWrite = React.useCallback(() => {
    isInternalScrollWriteRef.current = false;
    if (internalScrollWriteTimeoutRef.current === null) return;
    clearTimeout(internalScrollWriteTimeoutRef.current);
    internalScrollWriteTimeoutRef.current = null;
  }, []);

  const markInternalScrollWrite = React.useCallback(() => {
    isInternalScrollWriteRef.current = true;
    if (internalScrollWriteTimeoutRef.current !== null) {
      clearTimeout(internalScrollWriteTimeoutRef.current);
    }
    internalScrollWriteTimeoutRef.current = setTimeout(() => {
      internalScrollWriteTimeoutRef.current = null;
      isInternalScrollWriteRef.current = false;
    }, VIEWER_DOCUMENT_INTERNAL_SCROLL_SUPPRESS_MS);
  }, []);

  const resetViewportForKey = React.useCallback(
    (element: HTMLDivElement, key: unknown) => {
      cancelPendingScrollRestore();
      viewportResetKeyRef.current = key;
      scrollPageOffsetRef.current = 0;
      resetGeometryTransaction(element);
      scrollIntent.reset();
      markInternalScrollWrite();
      setViewportPhysicalScrollTop(element, 0);
      element.scrollTo?.({ top: 0, behavior: "auto" });
    },
    [
      cancelPendingScrollRestore,
      markInternalScrollWrite,
      resetGeometryTransaction,
      scrollIntent,
    ],
  );

  const setViewportElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element;
      if (element && !Object.is(viewportResetKeyRef.current, resetKey)) {
        resetViewportForKey(element, resetKey);
      }
      setViewportElementState(element);
    },
    [resetKey, resetViewportForKey],
  );

  const readScrollMetrics = React.useCallback(
    () =>
      readViewerDocumentScrollMetrics({
        layout,
        scrollMapper,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportElement: viewportElementRef.current,
      }),
    [layout, scrollMapper],
  );

  const syncViewportScrollPosition = React.useCallback(
    (viewportElement: HTMLDivElement, blockSize = layout.blockSize) => {
      const metrics = readViewerDocumentScrollMetrics({
        layout: {
          ...layout,
          blockSize,
        },
        scrollMapper,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportElement,
      });

      if (metrics.physicalScrollSize >= blockSize) {
        const nextMetrics = {
          ...metrics,
          scrollPageOffset: hasViewerDocumentScrollPageOffset(
            scrollPageOffsetRef.current,
          )
            ? metrics.scrollPageOffset
            : 0,
        };
        scrollPageOffsetRef.current = nextMetrics.scrollPageOffset;
        cacheReadingAnchor(nextMetrics);
        cacheVisualLayerRect(viewportElement);
        return nextMetrics;
      }

      const position = scrollMapper.resolvePhysicalScrollPosition({
        blockSize,
        logicalScrollTop: metrics.scrollTop,
        scrollPageOffset: metrics.scrollPageOffset,
        viewportBlockSize: metrics.viewportBlockSize,
      });
      scrollPageOffsetRef.current = position.scrollPageOffset;
      markInternalScrollWrite();
      setViewportPhysicalScrollTop(viewportElement, position.physicalScrollTop);

      const nextMetrics = {
        ...metrics,
        physicalScrollTop: position.physicalScrollTop,
        scrollPageOffset: position.scrollPageOffset,
      };
      cacheReadingAnchor(nextMetrics);
      cacheVisualLayerRect(viewportElement);
      return nextMetrics;
    },
    [
      cacheReadingAnchor,
      cacheVisualLayerRect,
      layout,
      markInternalScrollWrite,
      scrollMapper,
    ],
  );

  const syncScrollPosition = React.useCallback(() => {
    const viewportElement = viewportElementRef.current;
    return viewportElement ? syncViewportScrollPosition(viewportElement) : null;
  }, [syncViewportScrollPosition]);

  const schedulePendingScrollRestore = React.useCallback(
    (restore: PendingViewerDocumentScrollRestore) => {
      pendingScrollRestoreRef.current = restore;
      if (pendingScrollRestoreFrameRef.current !== 0) return;
      pendingScrollRestoreFrameRef.current = requestAnimationFrame(() => {
        pendingScrollRestoreFrameRef.current = 0;
        flushPendingScrollRestoreRef.current();
      });
    },
    [],
  );

  const resolveLogicalScrollPosition = React.useCallback(
    (viewportElement: HTMLDivElement, targetTop: number) => {
      const viewportBlockSize = viewportElement.clientHeight;
      const position = scrollMapper.resolvePhysicalScrollPosition({
        blockSize: layout.blockSize,
        logicalScrollTop: targetTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize,
      });
      const expectedPhysicalScrollSize = scrollMapper.getPhysicalScrollSize({
        blockSize: layout.blockSize,
        viewportBlockSize,
      });

      return {
        expectedMaxPhysicalScrollTop: Math.max(
          0,
          expectedPhysicalScrollSize - viewportBlockSize,
        ),
        position,
      };
    },
    [layout.blockSize, scrollMapper],
  );

  const applyLogicalScrollTop = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      targetTop: number,
      options: ScrollToOptions,
      {
        allowDefer,
        preservePhysicalScrollTop = false,
      }: { allowDefer: boolean; preservePhysicalScrollTop?: boolean },
    ) => {
      if (preservePhysicalScrollTop) {
        scrollPageOffsetRef.current = targetTop - viewportElement.scrollTop;
        cacheReadingAnchor({
          scrollTop: targetTop,
          viewportBlockSize: viewportElement.clientHeight,
        });
        cacheVisualLayerRect(viewportElement);
        return true;
      }

      const { expectedMaxPhysicalScrollTop, position } =
        resolveLogicalScrollPosition(viewportElement, targetTop);
      const currentMaxPhysicalScrollTop =
        getViewportMaxPhysicalScrollTop(viewportElement);
      const shouldDefer =
        allowDefer &&
        position.physicalScrollTop >
          currentMaxPhysicalScrollTop +
            VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
        position.physicalScrollTop <=
          expectedMaxPhysicalScrollTop +
            VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;

      if (shouldDefer) {
        schedulePendingScrollRestore({
          attempts: 0,
          options: {
            ...options,
            behavior: "auto",
          },
          targetTop,
        });
        return false;
      }

      scrollPageOffsetRef.current = position.scrollPageOffset;
      markInternalScrollWrite();
      scrollViewportToPhysicalTop(viewportElement, position.physicalScrollTop, {
        behavior: "auto",
        ...options,
      });
      return true;
    },
    [
      cacheReadingAnchor,
      cacheVisualLayerRect,
      markInternalScrollWrite,
      resolveLogicalScrollPosition,
      schedulePendingScrollRestore,
    ],
  );

  const flushPendingScrollRestore = React.useCallback(() => {
    const pendingRestore = pendingScrollRestoreRef.current;
    const viewportElement = viewportElementRef.current;
    if (!pendingRestore || !viewportElement) return;

    const { expectedMaxPhysicalScrollTop, position } =
      resolveLogicalScrollPosition(viewportElement, pendingRestore.targetTop);
    const currentMaxPhysicalScrollTop =
      getViewportMaxPhysicalScrollTop(viewportElement);
    const shouldWaitForRange =
      position.physicalScrollTop >
        currentMaxPhysicalScrollTop + VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
      position.physicalScrollTop <=
        expectedMaxPhysicalScrollTop +
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
      pendingRestore.attempts < VIEWER_DOCUMENT_SCROLL_RESTORE_MAX_FRAMES;

    if (shouldWaitForRange) {
      schedulePendingScrollRestore({
        ...pendingRestore,
        attempts: pendingRestore.attempts + 1,
      });
      return;
    }

    pendingScrollRestoreRef.current = null;
    scrollPageOffsetRef.current = position.scrollPageOffset;
    markInternalScrollWrite();
    scrollViewportToPhysicalTop(
      viewportElement,
      position.physicalScrollTop,
      pendingRestore.options,
    );
  }, [
    markInternalScrollWrite,
    resolveLogicalScrollPosition,
    schedulePendingScrollRestore,
  ]);

  useKeyedLayoutEffect(joinEffectKey([flushPendingScrollRestore]), () => {
    flushPendingScrollRestoreRef.current = flushPendingScrollRestore;
    flushPendingScrollRestore();
  });

  const materializeScrollPageOffset = React.useCallback(() => {
    const viewportElement = viewportElementRef.current;
    if (
      !viewportElement ||
      !hasViewerDocumentScrollPageOffset(scrollPageOffsetRef.current)
    ) {
      return;
    }

    const metrics = readViewerDocumentScrollMetrics({
      layout,
      scrollMapper,
      scrollPageOffset: scrollPageOffsetRef.current,
      viewportElement,
    });
    const position = scrollMapper.resolvePhysicalScrollPosition({
      blockSize: layout.blockSize,
      logicalScrollTop: metrics.scrollTop,
      scrollPageOffset: 0,
      viewportBlockSize: metrics.viewportBlockSize,
    });
    scrollPageOffsetRef.current = position.scrollPageOffset;
    markInternalScrollWrite();
    scrollViewportToPhysicalTop(viewportElement, position.physicalScrollTop, {
      behavior: "auto",
    });
    cacheReadingAnchor({
      scrollTop: metrics.scrollTop,
      viewportBlockSize: metrics.viewportBlockSize,
    });
    cacheVisualLayerRect(viewportElement);
  }, [
    cacheReadingAnchor,
    cacheVisualLayerRect,
    layout,
    markInternalScrollWrite,
    scrollMapper,
  ]);

  const scrollViewportToLogicalTop = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      targetTop: number,
      options?: ScrollToOptions,
      behavior?: {
        preservePhysicalScrollTop?: boolean;
      },
    ) => {
      applyLogicalScrollTop(
        viewportElement,
        targetTop,
        {
          behavior: "auto",
          ...options,
        },
        {
          allowDefer: true,
          preservePhysicalScrollTop: behavior?.preservePhysicalScrollTop,
        },
      );
      cacheReadingAnchor({
        scrollTop: targetTop,
        viewportBlockSize: viewportElement.clientHeight,
      });
    },
    [applyLogicalScrollTop, cacheReadingAnchor],
  );

  const scrollViewportToResolvedTarget = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      target: ViewerDocumentResolvedScrollTarget,
      options: ScrollToOptions,
    ) => {
      const physicalScrollSize = scrollMapper.getPhysicalScrollSize({
        blockSize: layout.blockSize,
        viewportBlockSize: viewportElement.clientHeight,
      });
      const position =
        physicalScrollSize < layout.blockSize
          ? scrollMapper.resolvePhysicalScrollPosition({
              blockSize: layout.blockSize,
              logicalScrollTop: target.top,
              scrollPageOffset: scrollPageOffsetRef.current,
              viewportBlockSize: viewportElement.clientHeight,
            })
          : {
              physicalScrollTop: Math.max(0, target.top),
              scrollPageOffset: 0,
            };
      scrollPageOffsetRef.current = position.scrollPageOffset;
      viewportElement.scrollTo({
        top: position.physicalScrollTop,
        ...(target.left == null ? null : { left: target.left }),
        ...options,
      });
    },
    [layout.blockSize, scrollMapper],
  );

  useKeyedLayoutEffect(
    joinEffectKey([
      copyScrollTarget,
      cacheAnchor,
      cacheReadingAnchor,
      cacheVisualLayerRect,
      classifyLayoutChange,
      commit,
      layout,
      prepare,
      recordStableState,
      resetKey,
      resetGeometryTransaction,
      resolveScrollTarget,
      scrollIntent,
      scrollMapper,
      scrollViewportToLogicalTop,
      scrollViewportToResolvedTarget,
      syncViewportScrollPosition,
    ]),
    () => {
      const previousLayout = committedLayoutRef.current;
      const previousResetKey = committedResetKeyRef.current;
      committedLayoutRef.current = layout;
      committedResetKeyRef.current = resetKey;

      const viewportElement = viewportElementRef.current;
      if (!viewportElement) return;

      const layoutChange = classifyLayoutChange({
        previousLayout,
        previousResetKey,
      });
      if (layoutChange === "reset") {
        resetGeometryTransaction(viewportElement);
        return;
      }

      const currentLogicalScrollTop = scrollMapper.getLogicalScrollTop({
        blockSize: layout.blockSize,
        physicalScrollTop: viewportElement.scrollTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize: viewportElement.clientHeight,
      });
      if (layoutChange !== "geometry") {
        recordStableState({
          clearTransition:
            layoutChange === "metadata" && !layout.isTransitioning,
          scrollTop: currentLogicalScrollTop,
          viewportBlockSize: viewportElement.clientHeight,
          viewportElement,
        });
        return;
      }

      const activeIntent = scrollIntent.current();
      const transition = layout.transition;
      if (
        activeIntent.kind === "programmatic" &&
        resolveScrollTarget &&
        transition?.source !== "viewer-shell"
      ) {
        const metrics = syncViewportScrollPosition(viewportElement);
        const target = resolveScrollTarget({
          layout,
          scrollTop: metrics.scrollTop,
          target: activeIntent.target,
          viewportElement,
        });
        if (!target) return;

        const { intent, targetChanged } = scrollIntent.updateProgrammaticTarget(
          activeIntent,
          target,
        );

        if (targetChanged) {
          scrollViewportToResolvedTarget(viewportElement, target, {
            behavior: intent.behavior,
          });
          scrollIntent.scheduleProgrammaticCompletion(intent.sequence);
        }
        cacheVisualLayerRect(viewportElement);
        return;
      }

      const previousLogicalScrollTop = scrollMapper.getLogicalScrollTop({
        blockSize: previousLayout.blockSize,
        physicalScrollTop: viewportElement.scrollTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize: viewportElement.clientHeight,
      });
      const viewportBlockSize = viewportElement.clientHeight;
      const transaction = prepare({
        previousLayout,
        scrollTop: previousLogicalScrollTop,
        viewportBlockSize,
      });
      if (!transaction) return;

      if (transaction.shouldRestoreScroll) {
        const targetTop = layout.getReadingAnchorScrollTop({
          anchor: transaction.anchor,
          viewportBlockSize: transaction.viewportBlockSize,
        });
        if (targetTop != null) {
          // Shell motions always rebase (commit-then-relax rebases scroll in
          // the slide-start commit), so the restore is a real scroll write.
          scrollViewportToLogicalTop(viewportElement, targetTop);
        } else {
          cacheAnchor({
            anchor: transaction.anchor,
            viewportBlockSize,
          });
        }
      } else {
        cacheAnchor({
          anchor: transaction.anchor,
          viewportBlockSize: transaction.viewportBlockSize,
        });
      }

      commit({
        transaction,
        viewportElement,
      });
    },
  );

  const handleScroll = React.useCallback((): ViewerDocumentScrollEventResult => {
    const viewportElement = viewportElementRef.current;
    if (viewportElement && isInternalScrollWriteRef.current) {
      const metrics = readScrollMetrics();
      cacheReadingAnchor(metrics);
      cacheVisualLayerRect(viewportElement);
      return { source: "internal" };
    }

    if (viewportElement) {
      syncViewportScrollPosition(viewportElement);
    }

    const activeIntent = scrollIntent.current();
    if (activeIntent.kind === "programmatic") {
      scrollIntent.scheduleProgrammaticCompletion(activeIntent.sequence);
      return { source: "programmatic" };
    } else {
      scrollIntent.markUser();
      return { source: "user" };
    }
  }, [
    cacheReadingAnchor,
    cacheVisualLayerRect,
    readScrollMetrics,
    scrollIntent,
    syncViewportScrollPosition,
  ]);

  const markUserScrollIntent = React.useCallback(() => {
    materializeScrollPageOffset();
    cancelPendingScrollRestore();
    scrollIntent.markUser();
  }, [cancelPendingScrollRestore, materializeScrollPageOffset, scrollIntent]);

  useKeyedMountEffect(joinEffectKey([resetKey, resetViewportForKey]), () => {
    if (!didMountResetEffectRef.current) {
      didMountResetEffectRef.current = true;
      return;
    }
    const viewportElement = viewportElementRef.current;
    if (viewportElement) {
      resetViewportForKey(viewportElement, resetKey);
    }
  });

  useKeyedMountEffect(
    joinEffectKey([markUserScrollIntent, scrollIntent, viewportElement]),
    () => {
      const viewportElement = viewportElementRef.current;
      if (!viewportElement) return;

      const handleScrollEnd = () => {
        const activeIntent = scrollIntent.current();
        if (activeIntent.kind === "programmatic") {
          scrollIntent.completeProgrammatic(activeIntent.sequence);
        } else {
          scrollIntent.reset();
        }
      };

      viewportElement.addEventListener?.("wheel", markUserScrollIntent, {
        passive: true,
      });
      viewportElement.addEventListener?.("touchstart", markUserScrollIntent, {
        passive: true,
      });
      viewportElement.addEventListener?.("pointerdown", markUserScrollIntent);
      viewportElement.addEventListener?.("keydown", markUserScrollIntent);
      viewportElement.addEventListener?.("scrollend", handleScrollEnd);

      return () => {
        viewportElement.removeEventListener?.("wheel", markUserScrollIntent);
        viewportElement.removeEventListener?.(
          "touchstart",
          markUserScrollIntent,
        );
        viewportElement.removeEventListener?.(
          "pointerdown",
          markUserScrollIntent,
        );
        viewportElement.removeEventListener?.("keydown", markUserScrollIntent);
        viewportElement.removeEventListener?.("scrollend", handleScrollEnd);
      };
    },
  );

  const scrollToTarget = React.useCallback(
    (target: Target, options?: ScrollToOptions) => {
      const viewportElement = viewportElementRef.current;
      const metrics = readScrollMetrics();
      const resolvedTarget =
        viewportElement && resolveScrollTarget
          ? resolveScrollTarget({
              layout,
              scrollTop: metrics.scrollTop,
              target,
              viewportElement,
            })
          : null;
      if (!viewportElement || !resolvedTarget) return;

      cancelPendingScrollRestore();
      const behavior = options?.behavior ?? "smooth";
      const intent = scrollIntent.startProgrammatic({
        behavior,
        copyScrollTarget,
        resolvedTarget,
        target,
      });
      scrollViewportToResolvedTarget(viewportElement, resolvedTarget, {
        behavior: "smooth",
        ...options,
      });
      scrollIntent.scheduleProgrammaticCompletion(intent.sequence);
    },
    [
      cancelPendingScrollRestore,
      copyScrollTarget,
      layout,
      readScrollMetrics,
      resolveScrollTarget,
      scrollIntent,
      scrollViewportToResolvedTarget,
    ],
  );
  const getViewportElement = React.useCallback(
    () => viewportElementRef.current,
    [],
  );

  useMountEffect(() => () => {
    clearInternalScrollWrite();
    cancelPendingScrollRestore();
    cancelGeometryTransaction();
    scrollIntent.clearProgrammaticTimeout();
  });

  return React.useMemo(
    () => ({
      getScrollMetrics: readScrollMetrics,
      getViewportElement,
      handleScroll,
      scrollToTarget,
      scrollViewportToLogicalTop,
      setViewportElement,
      syncScrollPosition,
      viewportElement,
    }),
    [
      getViewportElement,
      handleScroll,
      readScrollMetrics,
      scrollToTarget,
      scrollViewportToLogicalTop,
      setViewportElement,
      syncScrollPosition,
      viewportElement,
    ],
  );
}

function useViewerDocumentScrollIntentController<Target>() {
  const scrollIntentRef = React.useRef<ViewerDocumentScrollIntent<Target>>({
    kind: "idle",
  });
  const scrollIntentSequenceRef = React.useRef(0);
  const programmaticScrollIdleTimeoutRef = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null);

  const clearProgrammaticTimeout = React.useCallback(() => {
    if (programmaticScrollIdleTimeoutRef.current) {
      clearTimeout(programmaticScrollIdleTimeoutRef.current);
      programmaticScrollIdleTimeoutRef.current = null;
    }
  }, []);

  const reset = React.useCallback(() => {
    clearProgrammaticTimeout();
    scrollIntentRef.current = { kind: "idle" };
  }, [clearProgrammaticTimeout]);

  const completeProgrammatic = React.useCallback(
    (sequence: number) => {
      if (
        scrollIntentRef.current.kind === "programmatic" &&
        scrollIntentRef.current.sequence === sequence
      ) {
        scrollIntentRef.current = { kind: "idle" };
      }
      clearProgrammaticTimeout();
    },
    [clearProgrammaticTimeout],
  );

  const scheduleProgrammaticCompletion = React.useCallback(
    (sequence: number) => {
      clearProgrammaticTimeout();
      programmaticScrollIdleTimeoutRef.current = setTimeout(() => {
        completeProgrammatic(sequence);
      }, VIEWER_DOCUMENT_SCROLL_IDLE_MS);
    },
    [clearProgrammaticTimeout, completeProgrammatic],
  );

  const markUser = React.useCallback(() => {
    clearProgrammaticTimeout();
    scrollIntentRef.current = { kind: "user" };
  }, [clearProgrammaticTimeout]);

  const startProgrammatic = React.useCallback(
    ({
      behavior,
      copyScrollTarget,
      resolvedTarget,
      target,
    }: {
      behavior: ScrollBehavior;
      copyScrollTarget?: (target: Target) => Target;
      resolvedTarget: ViewerDocumentResolvedScrollTarget;
      target: Target;
    }) => {
      const sequence = scrollIntentSequenceRef.current + 1;
      scrollIntentSequenceRef.current = sequence;
      clearProgrammaticTimeout();

      const intent: Extract<
        ViewerDocumentScrollIntent<Target>,
        { kind: "programmatic" }
      > = {
        behavior,
        kind: "programmatic",
        sequence,
        target: copyScrollTarget ? copyScrollTarget(target) : target,
        targetLeft: resolvedTarget.left,
        targetTop: resolvedTarget.top,
      };
      scrollIntentRef.current = intent;
      return intent;
    },
    [clearProgrammaticTimeout],
  );

  const updateProgrammaticTarget = React.useCallback(
    (
      intent: Extract<
        ViewerDocumentScrollIntent<Target>,
        { kind: "programmatic" }
      >,
      target: ViewerDocumentResolvedScrollTarget,
    ) => {
      const targetChanged =
        Math.abs(intent.targetTop - target.top) >
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON ||
        Math.abs((intent.targetLeft ?? 0) - (target.left ?? 0)) >
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;
      const nextIntent = {
        ...intent,
        targetLeft: target.left,
        targetTop: target.top,
      };
      scrollIntentRef.current = nextIntent;
      return { intent: nextIntent, targetChanged };
    },
    [],
  );

  useKeyedMountEffect(joinEffectKey([clearProgrammaticTimeout]), () => () => {
    clearProgrammaticTimeout();
  });

  return React.useMemo(
    () => ({
      clearProgrammaticTimeout,
      completeProgrammatic,
      current: () => scrollIntentRef.current,
      markUser,
      reset,
      scheduleProgrammaticCompletion,
      startProgrammatic,
      updateProgrammaticTarget,
    }),
    [
      clearProgrammaticTimeout,
      completeProgrammatic,
      markUser,
      reset,
      scheduleProgrammaticCompletion,
      startProgrammatic,
      updateProgrammaticTarget,
    ],
  );
}

function readViewerDocumentScrollMetrics<Anchor>({
  layout,
  scrollMapper,
  scrollPageOffset,
  viewportElement,
}: {
  layout: ViewerDocumentLayoutModel<Anchor>;
  scrollMapper: ViewerDocumentScrollMapper;
  scrollPageOffset: number;
  viewportElement: HTMLDivElement | null;
}): ViewerDocumentScrollMetrics {
  const viewportBlockSize = viewportElement?.clientHeight ?? 0;
  const physicalScrollTop = viewportElement?.scrollTop ?? 0;
  const physicalScrollSize = scrollMapper.getPhysicalScrollSize({
    blockSize: layout.blockSize,
    viewportBlockSize,
  });
  const isRebased = physicalScrollSize < layout.blockSize;
  const hasLogicalOffset = hasViewerDocumentScrollPageOffset(scrollPageOffset);
  const shouldUseLogicalOffset = isRebased || hasLogicalOffset;

  return {
    physicalScrollSize,
    physicalScrollTop,
    scrollPageOffset: shouldUseLogicalOffset ? scrollPageOffset : 0,
    scrollTop: shouldUseLogicalOffset
      ? scrollMapper.getLogicalScrollTop({
          blockSize: layout.blockSize,
          physicalScrollTop,
          scrollPageOffset,
          viewportBlockSize,
        })
      : Math.max(0, physicalScrollTop),
    viewportBlockSize,
  };
}

function hasViewerDocumentScrollPageOffset(scrollPageOffset: number) {
  return Math.abs(scrollPageOffset) > VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;
}

function scrollViewportToPhysicalTop(
  viewportElement: HTMLDivElement,
  targetTop: number,
  options: ScrollToOptions,
) {
  if (
    Math.abs(viewportElement.scrollTop - targetTop) <=
    VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON
  ) {
    return;
  }

  if (typeof viewportElement.scrollTo === "function") {
    viewportElement.scrollTo({
      top: targetTop,
      ...options,
    });
    return;
  }

  setViewportPhysicalScrollTop(viewportElement, targetTop);
}

function getViewportMaxPhysicalScrollTop(viewportElement: HTMLDivElement) {
  return Math.max(
    0,
    viewportElement.scrollHeight - viewportElement.clientHeight,
  );
}

function setViewportPhysicalScrollTop(
  viewportElement: HTMLDivElement,
  targetTop: number,
) {
  if (
    Math.abs(viewportElement.scrollTop - targetTop) <=
    VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON
  ) {
    return;
  }

  viewportElement.scrollTop = targetTop;
}

import type * as React from "react";

export type ViewerSidebarMode = "inline" | "overlay";
export type ViewerSidebarRequestedMode = "auto" | ViewerSidebarMode;
export type ViewerSidebarGapTransition = "width" | "none";
export type ViewerSidebarState = "expanded" | "collapsed";
export type ViewerSidebarSide = "left" | "right";
export type ViewerSidebarCollapsible = "offcanvas" | "none";
export type ViewerDocumentFrameAlign = "start" | "center" | "end";
export type ViewerGeometryTransitionPhase = "idle" | "sliding";

export type ViewerDocumentReadingAnchorInput = {
  scrollTop: number;
  viewportBlockSize: number;
};

export type ViewerDocumentReadingAnchorTarget<Anchor> = {
  anchor: Anchor;
  viewportBlockSize: number;
};

export type ViewerDocumentTransitionSource =
  | "none"
  | "viewer-shell"
  | "document-layout";

// Commit-then-relax: layout commits its target inside the motion's first
// frame and scroll rebases in the same commit, so there is no frozen layout
// and no deferred scroll left in the vocabulary.
export type ViewerDocumentLayoutPolicy = "live" | "target";
export type ViewerDocumentScrollPolicy = "preserve" | "rebase";
export type ViewerDocumentVisualPolicy =
  | "none"
  | "document-flip"
  | "shell-transform";

export type ViewerDocumentTransition = {
  layoutPolicy: ViewerDocumentLayoutPolicy;
  scrollPolicy: ViewerDocumentScrollPolicy;
  source: ViewerDocumentTransitionSource;
  transitionId: number | string | null;
  visualPolicy: ViewerDocumentVisualPolicy;
};

export type ViewerDocumentLayoutModel<Anchor> = {
  blockSize: number;
  captureReadingAnchor: (
    input: ViewerDocumentReadingAnchorInput,
  ) => Anchor | null;
  getReadingAnchorScrollTop: (
    target: ViewerDocumentReadingAnchorTarget<Anchor>,
  ) => number | null;
  inlineSize: number;
  isTransitioning?: boolean;
  transition?: ViewerDocumentTransition;
};

export type ViewerDocumentPhysicalScrollPosition = {
  physicalScrollTop: number;
  scrollPageOffset: number;
};

export type ViewerDocumentResolvedScrollTarget = {
  left?: number;
  top: number;
};

export type ViewerDocumentScrollMapper = {
  getLogicalScrollTop: (input: {
    blockSize: number;
    physicalScrollTop: number;
    scrollPageOffset: number;
    viewportBlockSize: number;
  }) => number;
  getPhysicalScrollSize: (input: {
    blockSize: number;
    viewportBlockSize: number;
  }) => number;
  resolvePhysicalScrollPosition: (input: {
    blockSize: number;
    logicalScrollTop: number;
    scrollPageOffset: number;
    viewportBlockSize: number;
  }) => ViewerDocumentPhysicalScrollPosition;
};

export type ViewerDocumentScrollMetrics = {
  physicalScrollSize: number;
  physicalScrollTop: number;
  scrollPageOffset: number;
  scrollTop: number;
  viewportBlockSize: number;
};

export type ViewerDocumentScrollTargetResolver<Anchor, Target> = (input: {
  layout: ViewerDocumentLayoutModel<Anchor>;
